import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum MemberStage {
  VISITOR = 'VISITOR',
  NEW_MEMBER = 'NEW_MEMBER',
  ACTIVE_MEMBER = 'ACTIVE_MEMBER',
  LEADER_IN_TRAINING = 'LEADER_IN_TRAINING',
  LEADER = 'LEADER'
}

export interface Member {
  id: string;
  name: string;
  email: string;
  phone: string;
  stage: MemberStage;
  lastActivity: Date;
  engagementScore: number; // 0-100
  assignedLeaderId?: string;
  registrationDate: Date;
  channel: 'QR_CODE' | 'FACEBOOK' | 'INSTAGRAM' | 'WEBSITE' | 'MANUAL';
}

export interface AnalyticsData {
  stageDistribution: { name: string; value: number }[];
  retentionRate: number;
  conversionTime: string; // Average time to next stage
  weeklyGrowth: { day: string; count: number }[];
}

export interface AutomationRule {
  id: string;
  name: string;
  trigger: string;
  action: string;
  isActive: boolean;
}

import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateHumanizedMessage = async (memberName: string, stage: string, context: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Gere uma mensagem curta e amigável para o WhatsApp para um ${stage} chamado ${memberName}. 
      Contexto: ${context}. 
      Regras: Use tom acolhedor, evite parecer robô, use emojis moderadamente, máximo 2 parágrafos. 
      Linguagem: Português do Brasil.`,
    });
    return response.text;
  } catch (error) {
    console.error("Erro ao gerar mensagem humanizada:", error);
    return `Olá ${memberName}! Notamos sua presença e gostaríamos de saber como você está. Vamos conversar?`;
  }
};

import React from 'react';
import { Member, MemberStage } from '../types';
import { MoreVertical, MessageCircle, Calendar, ArrowRight } from 'lucide-react';

interface MemberCardProps {
  member: Member;
  onMove?: (id: string, newStage: MemberStage) => void;
}

const MemberCard: React.FC<MemberCardProps> = ({ member }) => {
  const getScoreColor = (score: number) => {
    if (score > 80) return 'text-green-600';
    if (score > 50) return 'text-amber-600';
    return 'text-red-600';
  };

  return (
    <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 hover:shadow-md transition-shadow group cursor-pointer">
      <div className="flex justify-between items-start mb-2">
        <h4 className="font-semibold text-slate-800 text-sm">{member.name}</h4>
        <button className="text-slate-400 hover:text-slate-600">
          <MoreVertical className="w-4 h-4" />
        </button>
      </div>

      <div className="flex items-center gap-2 mb-3 text-xs text-slate-500">
        <div className="flex items-center gap-1">
          <Calendar className="w-3 h-3" />
          {new Date(member.lastActivity).toLocaleDateString('pt-BR')}
        </div>
        <div className={`font-medium ${getScoreColor(member.engagementScore)}`}>
          Score: {member.engagementScore}%
        </div>
      </div>

      <div className="flex items-center justify-between pt-3 border-t border-slate-100">
        <div className="flex -space-x-2">
          {member.channel === 'INSTAGRAM' && (
            <div className="w-6 h-6 rounded-full bg-pink-100 flex items-center justify-center text-pink-600 border-2 border-white">
              <span className="text-[10px]">IG</span>
            </div>
          )}
          {member.channel === 'QR_CODE' && (
            <div className="w-6 h-6 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 border-2 border-white">
              <span className="text-[10px]">QR</span>
            </div>
          )}
        </div>

        <div className="flex gap-2">
          <button className="p-1.5 rounded-lg bg-emerald-50 text-emerald-600 hover:bg-emerald-100">
            <MessageCircle className="w-4 h-4" />
          </button>
          <button className="p-1.5 rounded-lg bg-slate-50 text-slate-600 hover:bg-slate-100">
            <ArrowRight className="w-4 h-4" />
          </button>
        </div>
      </div>
    </div>
  );
};

export default MemberCard;

