const MemberCard: React.FC<MemberCardProps> = ({ member, onMove }) => {
  const [isGenerating, setIsGenerating] = useState(false);

  const getScoreColor = (score: number) => {
    if (score > 80) return 'text-green-600';
    if (score > 50) return 'text-amber-600';
    return 'text-red-600';
  };

  const handleNextStage = () => {
    const currentIndex = STAGES.findIndex(s => s.id === member.stage);
    if (currentIndex < STAGES.length - 1 && onMove) {
      onMove(member.id, STAGES[currentIndex + 1].id as MemberStage);
    }
  };

  const handleGenerateMessage = async () => {
    if (isGenerating) return;
    setIsGenerating(true);
    const stageLabel = STAGES.find(s => s.id === member.stage)?.label || member.stage;
    try {
      const msg = await generateHumanizedMessage(
        member.name, 
        stageLabel, 
        "Contato caloroso de acompanhamento da liderança"
      );
      alert(`Mensagem Gerada para ${member.name}:\n\n${msg}`);
    } catch (err) {
      console.error(err);
    } finally {
      setIsGenerating(false);
    }
  };

  const isAtLastStage = STAGES.findIndex(s => s.id === member.stage) === STAGES.length - 1;

  return (
    <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 hover:shadow-md transition-shadow group cursor-pointer">
      <div className="flex justify-between items-start mb-2">
        <h4 className="font-semibold text-slate-800 text-sm">{member.name}</h4>
        <button className="text-slate-400 hover:text-slate-600">
          <MoreVertical className="w-4 h-4" />
        </button>
      </div>

      <div className="flex items-center gap-2 mb-3 text-xs text-slate-500">
        <div className="flex items-center gap-1">
          <Calendar className="w-3 h-3" />
          {new Date(member.lastActivity).toLocaleDateString('pt-BR')}
        </div>
        <div className={`font-medium ${getScoreColor(member.engagementScore)}`}>
          Score: {member.engagementScore}%
        </div>
      </div>

      <div className="flex items-center justify-between pt-3 border-t border-slate-100">
        <div className="flex -space-x-2">
          {member.channel === 'INSTAGRAM' && (
            <div className="w-6 h-6 rounded-full bg-pink-100 flex items-center justify-center text-pink-600 border-2 border-white" title="Instagram">
              <span className="text-[10px]">IG</span>
            </div>
          )}
          {member.channel === 'QR_CODE' && (
            <div className="w-6 h-6 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 border-2 border-white" title="QR Code">
              <span className="text-[10px]">QR</span>
            </div>
          )}
          {member.channel === 'MANUAL' && (
            <div className="w-6 h-6 rounded-full bg-slate-100 flex items-center justify-center text-slate-600 border-2 border-white" title="Manual">
              <span className="text-[10px]">M</span>
            </div>
          )}
        </div>

        <div className="flex gap-2">
          <button 
            onClick={handleGenerateMessage}
            disabled={isGenerating}
            className="p-1.5 rounded-lg bg-emerald-50 text-emerald-600 hover:bg-emerald-100 disabled:opacity-50"
            title="Gerar Mensagem IA"
          >
            {isGenerating ? <Loader2 className="w-4 h-4 animate-spin" /> : <MessageCircle className="w-4 h-4" />}
          </button>
          <button 
            onClick={handleNextStage}
            disabled={isAtLastStage}
            className={`p-1.5 rounded-lg bg-slate-50 text-slate-600 hover:bg-slate-100 disabled:opacity-30`}
            title={isAtLastStage ? "Estágio Final" : "Próximo Estágio"}
          >
            <ArrowRight className="w-4 h-4" />
          </button>
        </div>
      </div>
    </div>
  );
};

export default MemberCard;

