import React, { useState } from 'react';
import { 
  LayoutDashboard, 
  Columns, 
  Zap, 
  Settings, 
  Bell, 
  Search, 
  User,
  LogOut,
  ChevronRight,
  Menu,
  X,
  Save,
  Trash2
} from 'lucide-react';
import KanbanBoard from './components/KanbanBoard';
import AnalyticsDashboard from './components/AnalyticsDashboard';
import AutomationSettings from './components/AutomationSettings';
import { INITIAL_MEMBERS, INTEGRATIONS, STAGES } from './constants';
import { Member, MemberStage } from './types';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'kanban' | 'analytics' | 'automation'>('kanban');
  const [members, setMembers] = useState<Member[]>(INITIAL_MEMBERS);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  // Modal states
  const [isMemberModalOpen, setIsMemberModalOpen] = useState(false);
  const [editingMember, setEditingMember] = useState<Partial<Member> | null>(null);

  const moveMember = (id: string, nextStage: MemberStage) => {
    setMembers(prev => prev.map(m => m.id === id ? { ...m, stage: nextStage } : m));
  };

  const handleOpenAddModal = () => {
    setEditingMember({
      stage: MemberStage.VISITOR,
      channel: 'MANUAL',
      engagementScore: 10,
      registrationDate: new Date(),
      lastActivity: new Date()
    });
    setIsMemberModalOpen(true);
  };

  const handleOpenEditModal = (member: Member) => {
    setEditingMember(member);
    setIsMemberModalOpen(true);
  };

  const handleSaveMember = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingMember?.name) return;

    if (editingMember.id) {
      // Update
      setMembers(prev => prev.map(m => m.id === editingMember.id ? (editingMember as Member) : m));
    } else {
      // Create
      const newMember: Member = {
        ...(editingMember as Member),
        id: Math.random().toString(36).substr(2, 9),
      };
      setMembers(prev => [...prev, newMember]);
    }
    setIsMemberModalOpen(false);
  };

  const handleDeleteMember = (id: string) => {
    if (confirm("Deseja realmente remover este registro?")) {
      setMembers(prev => prev.filter(m => m.id !== id));
      setIsMemberModalOpen(false);
    }
  };

  const navItems = [
    { id: 'kanban', label: 'Pipeline', icon: <Columns className="w-5 h-5" /> },
    { id: 'analytics', label: 'Dashboard', icon: <LayoutDashboard className="w-5 h-5" /> },
    { id: 'automation', label: 'Automação', icon: <Zap className="w-5 h-5" /> },
  ];

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      {/* Sidebar */}
      <aside className={`bg-white border-r border-slate-200 transition-all duration-300 flex flex-col ${isSidebarOpen ? 'w-64' : 'w-20'}`}>
        <div className="p-6 flex items-center gap-3">
          <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white font-bold text-xl shadow-lg shadow-indigo-200">
            K
          </div>
          {isSidebarOpen && (
            <div className="flex flex-col">
              <span className="font-bold text-slate-800 leading-tight">Koinonia</span>
              <span className="text-[10px] text-slate-400 uppercase font-bold tracking-tighter">Growth CRM</span>
            </div>
          )}
        </div>

        <nav className="flex-1 mt-6 px-3 space-y-2">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id as any)}
              className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl transition-all ${
                activeTab === item.id 
                ? 'bg-indigo-50 text-indigo-700 font-semibold' 
                : 'text-slate-500 hover:bg-slate-50 hover:text-slate-800'
              }`}
            >
              <div className={activeTab === item.id ? 'text-indigo-600' : 'text-slate-400'}>
                {item.icon}
              </div>
              {isSidebarOpen && <span>{item.label}</span>}
              {activeTab === item.id && isSidebarOpen && <ChevronRight className="w-4 h-4 ml-auto" />}
            </button>
          ))}
        </nav>

        <div className="p-4 mt-auto border-t border-slate-100">
          {isSidebarOpen && (
            <div className="mb-4 bg-slate-50 rounded-xl p-3">
              <p className="text-[10px] font-bold text-slate-400 uppercase mb-2">Integrações</p>
              <div className="space-y-2">
                {INTEGRATIONS.slice(0, 3).map((integ, i) => (
                  <div key={i} className="flex items-center gap-2 text-xs text-slate-600">
                    {integ.icon}
                    <span className="truncate">{integ.name}</span>
                    <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 ml-auto" />
                  </div>
                ))}
              </div>
            </div>
          )}

          <button className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl text-slate-500 hover:bg-red-50 hover:text-red-600 transition-all`}>
            <LogOut className="w-5 h-5" />
            {isSidebarOpen && <span>Sair</span>}
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col overflow-hidden">
        {/* Header */}
        <header className="h-16 bg-white border-b border-slate-200 px-6 flex items-center justify-between z-10">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setIsSidebarOpen(!isSidebarOpen)}
              className="p-2 hover:bg-slate-50 rounded-lg text-slate-400"
            >
              {isSidebarOpen ? <X className="w-5 h-5" /> : <Menu className="w-5 h-5" />}
            </button>
            <div className="hidden md:flex items-center bg-slate-100 px-3 py-1.5 rounded-xl border border-slate-200">
              <Search className="w-4 h-4 text-slate-400" />
              <input 
                type="text" 
                placeholder="Buscar membro..." 
                className="bg-transparent border-none focus:ring-0 text-sm w-64 placeholder-slate-400 ml-2" 
              />
            </div>
          </div>

          <div className="flex items-center gap-4">
            <button className="relative p-2 text-slate-400 hover:bg-slate-50 rounded-lg">
              <Bell className="w-5 h-5" />
              <span className="absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full border-2 border-white"></span>
            </button>
            <div className="h-8 w-px bg-slate-200 mx-1"></div>
            <div className="flex items-center gap-3 pl-2">
              <div className="text-right hidden sm:block">
                <p className="text-sm font-bold text-slate-800 leading-none">Pastor Ricardo</p>
                <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">Admin Geral</p>
              </div>
              <div className="w-10 h-10 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600 border border-indigo-200 overflow-hidden">
                <img src="https://picsum.photos/id/64/100/100" alt="Avatar" />
              </div>
            </div>
          </div>
        </header>

        {/* Content Area */}
        <div className="flex-1 overflow-hidden relative">
          {activeTab === 'kanban' && (
            <KanbanBoard 
              members={members} 
              onMoveMember={moveMember} 
              onAddMember={handleOpenAddModal}
              onMemberClick={handleOpenEditModal}
            />
          )}
          {activeTab === 'analytics' && (
            <AnalyticsDashboard members={members} />
          )}
          {activeTab === 'automation' && (
            <AutomationSettings />
          )}
        </div>
      </main>

      {/* Member Modal (Add/Edit) */}
      {isMemberModalOpen && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl w-full max-w-lg shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center">
              <h3 className="text-lg font-bold text-slate-800">
                {editingMember?.id ? 'Detalhes do Membro' : 'Novo Visitante'}
              </h3>
              <button onClick={() => setIsMemberModalOpen(false)} className="p-2 hover:bg-slate-50 rounded-full text-slate-400">
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleSaveMember} className="p-6 space-y-4">
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-400 uppercase">Nome Completo</label>
                <input 
                  autoFocus
                  required
                  type="text" 
                  value={editingMember?.name || ''}
                  onChange={(e) => setEditingMember(prev => ({ ...prev, name: e.target.value }))}
                  className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none"
                  placeholder="Ex: João da Silva"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-400 uppercase">E-mail</label>
                  <input 
                    type="email" 
                    value={editingMember?.email || ''}
                    onChange={(e) => setEditingMember(prev => ({ ...prev, email: e.target.value }))}
                    className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl outline-none"
                    placeholder="joao@exemplo.com"
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-400 uppercase">WhatsApp</label>
                  <input 
                    type="text" 
                    value={editingMember?.phone || ''}
                    onChange={(e) => setEditingMember(prev => ({ ...prev, phone: e.target.value }))}
                    className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl outline-none"
                    placeholder="+55 11 9..."
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-400 uppercase">Estágio Atual</label>
                  <select 
                    value={editingMember?.stage}
                    onChange={(e) => setEditingMember(prev => ({ ...prev, stage: e.target.value as MemberStage }))}
                    className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl outline-none"
                  >
                    {STAGES.map(s => <option key={s.id} value={s.id}>{s.label}</option>)}
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-400 uppercase">Canal de Origem</label>
                  <select 
                    value={editingMember?.channel}
                    onChange={(e) => setEditingMember(prev => ({ ...prev, channel: e.target.value as any }))}
                    className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl outline-none"
                  >
                    <option value="MANUAL">Manual</option>
                    <option value="QR_CODE">QR Code</option>
                    <option value="INSTAGRAM">Instagram</option>
                    <option value="FACEBOOK">Facebook</option>
                    <option value="WEBSITE">Website</option>
                  </select>
                </div>
              </div>

              <div className="pt-6 flex gap-3">
                {editingMember?.id && (
                  <button 
                    type="button"
                    onClick={() => handleDeleteMember(editingMember.id!)}
                    className="flex items-center gap-2 px-4 py-2 text-red-600 hover:bg-red-50 rounded-xl transition-colors font-medium"
                  >
                    <Trash2 className="w-4 h-4" /> Remover
                  </button>
                )}
                <div className="flex-1 flex justify-end gap-3">
                  <button 
                    type="button" 
                    onClick={() => setIsMemberModalOpen(false)}
                    className="px-6 py-2 text-slate-500 font-medium hover:bg-slate-50 rounded-xl"
                  >
                    Cancelar
                  </button>
                  <button 
                    type="submit"
                    className="flex items-center gap-2 px-6 py-2 bg-indigo-600 text-white font-bold rounded-xl hover:bg-indigo-700 shadow-lg shadow-indigo-100 transition-all active:scale-95"
                  >
                    <Save className="w-4 h-4" /> Salvar Alterações
                  </button>
                </div>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

export enum MemberStage {
  VISITOR = 'VISITOR',
  NEW_MEMBER = 'NEW_MEMBER',
  ACTIVE_MEMBER = 'ACTIVE_MEMBER',
  LEADER_IN_TRAINING = 'LEADER_IN_TRAINING',
  LEADER = 'LEADER'
}

export enum UserRole {
  ADMIN = 'ADMIN',
  PASTOR = 'PASTOR',
  LEADER = 'LEADER',
  VOLUNTEER = 'VOLUNTEER'
}

