                  <label className="text-xs font-bold text-slate-400 uppercase ml-1">WhatsApp</label>
                  <input 
                    type="text" 
                    value={editingMember?.phone || ''}
                    onChange={(e) => setEditingMember(prev => ({ ...prev, phone: e.target.value }))}
                    className="w-full px-5 py-3 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none"
                    placeholder="+55 11 9..."
                  />
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-400 uppercase ml-1">Áreas de Interesse</label>
                <div className="flex flex-wrap gap-2 pt-2">
                  {['Estudos Bíblicos', 'Música/Louvor', 'Ação Social', 'Jovens', 'Família', 'Infantil'].map(interest => (
                    <button 
                      key={interest}
                      type="button"
                      onClick={() => {
                        const current = editingMember?.interests || [];
                        const next = current.includes(interest) ? current.filter(i => i !== interest) : [...current, interest];
                        setEditingMember(prev => ({ ...prev, interests: next }));
                      }}
                      className={`px-4 py-2 rounded-xl text-xs font-bold transition-all border ${
                        editingMember?.interests?.includes(interest) 
                        ? 'bg-indigo-600 border-indigo-600 text-white shadow-md' 
                        : 'bg-white border-slate-200 text-slate-500 hover:border-indigo-300'
