                       </div>
                       <div className="space-y-1">
                          <label className="text-[10px] font-bold text-slate-400 uppercase">Fuso Horário</label>
                          <select className="w-full p-2.5 bg-slate-50 rounded-xl outline-none text-sm font-medium text-slate-800">
                             <option>(GMT-03:00) São Paulo</option>
