                       </div>
                    </div>
                  </section>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>

      {/* Member Modal (Add/Edit) */}
      {isMemberModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[40px] w-full max-w-2xl shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-300 border border-slate-100">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
              <div>
                <h3 className="text-2xl font-bold text-slate-800">
                  {editingMember?.id ? 'Editar Registro' : 'Novo Registro'}
                </h3>
                <p className="text-sm text-slate-400 font-medium">Preencha os dados do contato abaixo</p>
              </div>
              <button onClick={() => setIsMemberModalOpen(false)} className="p-3 hover:bg-white rounded-2xl text-slate-400 transition-all shadow-sm">
                <X className="w-6 h-6" />
              </button>
            </div>

            <form onSubmit={handleSaveMember} className="p-8 space-y-6 overflow-y-auto max-h-[70vh] scrollbar-hide">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-400 uppercase ml-1">Nome Completo</label>
                  <input 
                    autoFocus required type="text" 
                    value={editingMember?.name || ''}
                    onChange={(e) => setEditingMember(prev => ({ ...prev, name: e.target.value }))}
                    className="w-full px-5 py-3 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none font-medium text-slate-800"
                    placeholder="Nome completo do contato"
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-400 uppercase ml-1">Líder Responsável</label>
                  <select 
                    value={editingMember?.responsibleLeader || ''}
                    onChange={(e) => setEditingMember(prev => ({ ...prev, responsibleLeader: e.target.value }))}
                    className="w-full px-5 py-3 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none font-medium text-slate-800"
                  >
                    <option value="">Selecione um Líder</option>
                    {teamMembers.map(m => <option key={m.id} value={m.name}>{m.name}</option>)}
                  </select>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-400 uppercase ml-1">E-mail</label>
                  <input 
                    type="email" 
                    value={editingMember?.email || ''}
                    onChange={(e) => setEditingMember(prev => ({ ...prev, email: e.target.value }))}
                    className="w-full px-5 py-3 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-slate-800"
                    placeholder="email@exemplo.com"
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-400 uppercase ml-1">WhatsApp</label>
                  <input 
                    type="text" 
                    value={editingMember?.phone || ''}
                    onChange={(e) => setEditingMember(prev => ({ ...prev, phone: e.target.value }))}
                    className="w-full px-5 py-3 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-slate-800"
                    placeholder="+55 11 9..."
                  />
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-400 uppercase ml-1">Áreas de Interesse</label>
                <div className="flex flex-wrap gap-2 pt-2">
                  {['Estudos Bíblicos', 'Música/Louvor', 'Ação Social', 'Jovens', 'Família', 'Infantil'].map(interest => (
                    <button 
                      key={interest}
                      type="button"
                      onClick={() => {
                        const current = editingMember?.interests || [];
                        const next = current.includes(interest) ? current.filter(i => i !== interest) : [...current, interest];
                        setEditingMember(prev => ({ ...prev, interests: next }));
                      }}
                      className={`px-4 py-2 rounded-xl text-xs font-bold transition-all border ${
                        editingMember?.interests?.includes(interest) 
                        ? 'bg-indigo-600 border-indigo-600 text-white shadow-md' 
                        : 'bg-white border-slate-200 text-slate-500 hover:border-indigo-300'
                      }`}
                    >
                      {interest}
                    </button>
                  ))}
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-400 uppercase ml-1">Estágio na Jornada</label>
                  <select 
                    value={editingMember?.stage}
                    onChange={(e) => setEditingMember(prev => ({ ...prev, stage: e.target.value as MemberStage }))}
                    className="w-full px-5 py-3 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none font-bold text-indigo-700"
                  >
                    {STAGES.map(s => <option key={s.id} value={s.id}>{s.label}</option>)}
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-400 uppercase ml-1">Canal de Origem</label>
                  <select 
                    value={editingMember?.channel}
                    onChange={(e) => setEditingMember(prev => ({ ...prev, channel: e.target.value as any }))}
                    className="w-full px-5 py-3 bg-slate-50 border-none rounded-2xl outline-none text-slate-800"
                  >
                    <option value="MANUAL">Manual</option>
                    <option value="QR_CODE">QR Code</option>
                    <option value="INSTAGRAM">Instagram</option>
                    <option value="FACEBOOK">Facebook</option>
                    <option value="WEBSITE">Website</option>
                  </select>
                </div>
              </div>

              <div className="pt-8 flex gap-4">
                {editingMember?.id && (
                  <button 
                    type="button"
                    onClick={() => handleDeleteMember(editingMember.id!)}
                    className="flex items-center gap-2 px-6 py-4 text-red-600 hover:bg-red-50 rounded-2xl transition-all font-bold"
                  >
                    <Trash2 className="w-5 h-5" /> Excluir
                  </button>
                )}
                <div className="flex-1 flex justify-end gap-4">
                  <button 
                    type="button" 
                    onClick={() => setIsMemberModalOpen(false)}
                    className="px-8 py-4 text-slate-500 font-bold hover:bg-slate-50 rounded-2xl transition-all"
                  >
                    Cancelar
                  </button>
                  <button 
                    type="submit"
                    className="flex items-center gap-3 px-10 py-4 bg-indigo-600 text-white font-bold rounded-2xl hover:bg-indigo-700 shadow-xl shadow-indigo-100 transition-all active:scale-95"
                  >
                    <Save className="w-5 h-5" /> Salvar Cadastro
                  </button>
                </div>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { 
  LayoutDashboard, 
  Columns, 
  Zap, 
  Settings, 
  Bell, 
  Search, 
  User,
  LogOut,
  ChevronRight,
  Menu,
  X,
  Save,
  Trash2,
  Users as UsersIcon,
  Church as ChurchIcon,
  Contact as ContactIcon,
  CheckCircle,
  Plus,
  ArrowRight,
  Key,
  Globe,
  Palette,
  Clock,
  HelpCircle,
  ShieldCheck,
  Smartphone,
  List,
  LayoutGrid,
  MapPin,
  Upload,
  UserPlus,
  Edit2
} from 'lucide-react';
import KanbanBoard from './components/KanbanBoard';
import AnalyticsDashboard from './components/AnalyticsDashboard';
import AutomationSettings from './components/AutomationSettings';
import { INITIAL_MEMBERS, INTEGRATIONS, STAGES } from './constants';
import { Member, MemberStage, SystemUser, UserRole } from './types';

const App: React.FC = () => {
  // Appearance & UI State
  const [theme, setTheme] = useState<'light' | 'dark'>('light');
  const [viewMode, setViewMode] = useState<'blocks' | 'list'>('list');

  // Auth & Data State
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentUser, setCurrentUser] = useState<SystemUser | null>(null);
  const [teamMembers, setTeamMembers] = useState<SystemUser[]>([]);
  const [members, setMembers] = useState<Member[]>(INITIAL_MEMBERS);

  // Navigation State
  const [activeTab, setActiveTab] = useState<'kanban' | 'analytics' | 'automation' | 'team' | 'church' | 'contacts' | 'settings'>('kanban');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isProfileOpen, setIsProfileOpen] = useState(false);

  // Church Data State
  const [churchData, setChurchData] = useState({
    logo: '',
    name: '',
    cep: '',
    address: '',
    city: '',
    state: '',
    pastor: ''
  });

  // Modal states
  const [isMemberModalOpen, setIsMemberModalOpen] = useState(false);
  const [editingMember, setEditingMember] = useState<Partial<Member> | null>(null);

  const [isTeamModalOpen, setIsTeamModalOpen] = useState(false);
  const [editingTeamMember, setEditingTeamMember] = useState<Partial<SystemUser> | null>(null);

  const [isImportModalOpen, setIsImportModalOpen] = useState(false);

  // Login Form State
  const [loginForm, setLoginForm] = useState({ name: '', email: '', whatsapp: '', church: '', password: '' });

  const moveMember = (id: string, nextStage: MemberStage) => {
    setMembers(prev => prev.map(m => m.id === id ? { ...m, stage: nextStage } : m));
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const newUser: SystemUser = {
      id: Math.random().toString(36).substr(2, 9),
      name: loginForm.name || 'Eduardo Pietrafessa',
      email: loginForm.email || 'edu.pietrafessa@gmail.com',
      role: UserRole.ADMIN,
      church: loginForm.church || 'Igreja Central',
      avatar: 'https://picsum.photos/id/64/100/100'
    };
    setCurrentUser(newUser);
    setTeamMembers([newUser]); 
    setChurchData(prev => ({ ...prev, name: newUser.church, pastor: newUser.name }));
    setIsLoggedIn(true);
  };

  const handleCepBlur = async (cep: string) => {
    const cleanCep = cep.replace(/\D/g, '');
    if (cleanCep.length === 8) {
      try {
        const response = await fetch(`https://viacep.com.br/ws/${cleanCep}/json/`);
        const data = await response.json();
        if (!data.erro) {
          setChurchData(prev => ({
            ...prev,
            address: `${data.logradouro}, ${data.bairro}`,
            city: data.localidade,
            state: data.uf
          }));
        }
      } catch (error) {
        console.error("Erro ao buscar CEP:", error);
      }
    }
  };

  const handleOpenAddModal = () => {
    setEditingMember({
      stage: MemberStage.VISITOR,
      channel: 'MANUAL',
      engagementScore: 10,
      registrationDate: new Date(),
      lastActivity: new Date(),
      interests: [],
      responsibleLeader: ''
    });
    setIsMemberModalOpen(true);
  };

  const handleOpenEditModal = (member: Member) => {
    setEditingMember(member);
    setIsMemberModalOpen(true);
  };

  const handleSaveMember = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingMember?.name) return;

    if (editingMember.id) {
      setMembers(prev => prev.map(m => m.id === editingMember.id ? (editingMember as Member) : m));
    } else {
      const newMember: Member = {
        ...(editingMember as Member),
        id: Math.random().toString(36).substr(2, 9),
      };
      setMembers(prev => [...prev, newMember]);
    }
    setIsMemberModalOpen(false);
  };

  const handleDeleteMember = (id: string) => {
    if (confirm("Deseja realmente remover este registro?")) {
      setMembers(prev => prev.filter(m => m.id !== id));
      setIsMemberModalOpen(false);
    }
  };

  // Team Management Functions
  const handleOpenTeamModal = (user?: SystemUser) => {
    setEditingTeamMember(user || { role: UserRole.LEADER });
    setIsTeamModalOpen(true);
  };

  const handleSaveTeamMember = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingTeamMember?.name) return;

    if (editingTeamMember.id) {
      setTeamMembers(prev => prev.map(u => u.id === editingTeamMember.id ? (editingTeamMember as SystemUser) : u));
    } else {
      const newUser: SystemUser = {
        ...(editingTeamMember as SystemUser),
        id: Math.random().toString(36).substr(2, 9),
      };
      setTeamMembers(prev => [...prev, newUser]);
    }
    setIsTeamModalOpen(false);
  };

  const handleDeleteTeamMember = (id: string) => {
    if (id === currentUser?.id) {
      alert("Você não pode remover a si mesmo.");
      return;
    }
    if (confirm("Remover este membro da equipe?")) {
      setTeamMembers(prev => prev.filter(u => u.id !== id));
    }
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setCurrentUser(null);
    setIsProfileOpen(false);
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-indigo-900 flex items-center justify-center p-6 relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-full opacity-10 pointer-events-none">
          <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-indigo-400 rounded-full blur-[120px]"></div>
          <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-blue-400 rounded-full blur-[120px]"></div>
        </div>

        <div className="bg-white/95 backdrop-blur-md rounded-[40px] shadow-2xl w-full max-w-md overflow-hidden relative z-10">
          <div className="p-8 text-center bg-indigo-600 text-white">
            <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center mx-auto mb-4 shadow-xl">
              <span className="text-indigo-600 font-black text-3xl">K</span>
            </div>
