              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-400 uppercase ml-1">Estágio na Jornada</label>
                  <select 
                    value={editingMember?.stage}
