                    className="w-full px-5 py-3 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none font-black text-indigo-700 uppercase"
                  >
                    {STAGES.map(s => <option key={s.id} value={s.id}>{s.label}</option>)}
