                </div>
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-400 uppercase ml-1">Canal de Origem</label>
                  <select 
                    value={editingMember?.channel}
                    onChange={(e) => setEditingMember(prev => ({ ...prev, channel: e.target.value as any }))}
                    className="w-full px-5 py-3 bg-slate-50 border-none rounded-2xl outline-none font-bold text-slate-800"
                  >
                    <option value="MANUAL">Manual</option>
                    <option value="QR_CODE">QR Code</option>
                    <option value="INSTAGRAM">Instagram</option>
                    <option value="FACEBOOK">Facebook</option>
                    <option value="WEBSITE">Website</option>
                  </select>
                </div>
              </div>

              <div className="pt-8 flex gap-4">
                {editingMember?.id && (
                  <button 
                    type="button"
                    onClick={() => handleDeleteMember(editingMember.id!)}
                    className="flex items-center gap-2 px-6 py-4 text-red-600 hover:bg-red-50 rounded-2xl transition-all font-bold"
                  >
                    <Trash2 className="w-5 h-5" /> Excluir
                  </button>
                )}
                <div className="flex-1 flex justify-end gap-4">
                  <button 
                    type="button" 
                    onClick={() => setIsMemberModalOpen(false)}
                    className="px-8 py-4 text-slate-500 font-bold hover:bg-slate-50 rounded-2xl transition-all"
                  >
                    Cancelar
                  </button>
                  <button 
                    type="submit"
                    className="flex items-center gap-3 px-10 py-4 bg-indigo-600 text-white font-bold rounded-2xl hover:bg-indigo-700 shadow-xl shadow-indigo-100 transition-all active:scale-95"
                  >
                    <Save className="w-5 h-5" /> Salvar Registro
                  </button>
                </div>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Team Modal */}
      {isTeamModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[40px] w-full max-w-md shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-300">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-indigo-600 text-white">
              <h3 className="text-xl font-bold">{editingTeamMember?.id ? 'Editar Líder' : 'Novo Membro Equipe'}</h3>
              <button onClick={() => setIsTeamModalOpen(false)} className="p-2 hover:bg-white/20 rounded-xl transition-all"><X className="w-5 h-5" /></button>
            </div>
            <form onSubmit={handleSaveTeamMember} className="p-8 space-y-4">
               <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Nome</label>
                  <input required value={editingTeamMember?.name || ''} onChange={e => setEditingTeamMember({...editingTeamMember, name: e.target.value})} className="w-full p-3 bg-slate-100 rounded-xl outline-none font-bold text-slate-800" />
               </div>
               <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Email</label>
                  <input required type="email" value={editingTeamMember?.email || ''} onChange={e => setEditingTeamMember({...editingTeamMember, email: e.target.value})} className="w-full p-3 bg-slate-100 rounded-xl outline-none text-slate-800" />
               </div>
               <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Função / Cargo</label>
                  <select value={editingTeamMember?.role} onChange={e => setEditingTeamMember({...editingTeamMember, role: e.target.value as UserRole})} className="w-full p-3 bg-slate-100 rounded-xl outline-none font-bold text-slate-700">
                     {Object.values(UserRole).map(role => <option key={role} value={role}>{role}</option>)}
