      {/* Import Modal */}
      {isImportModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[100] flex items-center justify-center p-4">
           <div className="bg-white rounded-[40px] w-full max-w-lg shadow-2xl p-10 text-center animate-in zoom-in">
              <div className="w-20 h-20 bg-indigo-50 rounded-[32px] flex items-center justify-center text-indigo-600 mx-auto mb-6">
                 <Upload className="w-10 h-10" />
              </div>
              <h3 className="text-2xl font-black text-slate-800 mb-2">Importação Massiva</h3>
              <p className="text-slate-500 mb-8 font-medium">Selecione uma planilha (CSV/Excel) com os dados dos novos contatos.</p>

              <div className="border-2 border-dashed border-slate-200 rounded-3xl p-8 mb-8 hover:border-indigo-300 transition-all cursor-pointer group">
                 <p className="text-sm font-bold text-slate-400 group-hover:text-indigo-500">Clique para selecionar arquivo</p>
                 <p className="text-[10px] text-slate-300 mt-1 uppercase">Modelos: .csv, .xlsx</p>
