                 <button onClick={() => { alert('Processamento simulado iniciado...'); setIsImportModalOpen(false); }} className="flex-1 py-4 bg-indigo-600 text-white font-bold rounded-2xl shadow-xl active:scale-95">Processar Arquivo</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, Cell, LineChart, Line 
} from 'recharts';
import { TrendingUp, Users, Target, Activity, AlertTriangle } from 'lucide-react';
import { Member, MemberStage } from '../types';

interface AnalyticsDashboardProps {
  members: Member[];
}

const AnalyticsDashboard: React.FC<AnalyticsDashboardProps> = ({ members }) => {
  const COLORS = ['#3b82f6', '#10b981', '#6366f1', '#f59e0b', '#a855f7'];

  // Real-time calculated data
  const stageData = useMemo(() => [
    { name: 'Visitantes', value: members.filter(m => m.stage === MemberStage.VISITOR).length },
    { name: 'Novos', value: members.filter(m => m.stage === MemberStage.NEW_MEMBER).length },
    { name: 'Ativos', value: members.filter(m => m.stage === MemberStage.ACTIVE_MEMBER).length },
    { name: 'Em Treino', value: members.filter(m => m.stage === MemberStage.LEADER_IN_TRAINING).length },
    { name: 'Líderes', value: members.filter(m => m.stage === MemberStage.LEADER).length },
  ], [members]);

  // Mocked growth but scaled to total member count
  const growthData = useMemo(() => [
    { day: 'Seg', count: Math.floor(members.length * 0.1) },
    { day: 'Ter', count: Math.floor(members.length * 0.15) },
    { day: 'Qua', count: Math.floor(members.length * 0.12) },
    { day: 'Qui', count: Math.floor(members.length * 0.2) },
    { day: 'Sex', count: Math.floor(members.length * 0.18) },
    { day: 'Sáb', count: Math.floor(members.length * 0.25) },
    { day: 'Dom', count: Math.floor(members.length * 0.35) },
  ], [members]);

  const activeRate = useMemo(() => {
    const active = members.filter(m => m.stage === MemberStage.ACTIVE_MEMBER || m.stage === MemberStage.LEADER).length;
    return members.length > 0 ? Math.round((active / members.length) * 100) : 0;
  }, [members]);

  const avgEngagement = useMemo(() => {
    if (members.length === 0) return 0;
    return Math.round(members.reduce((acc, m) => acc + m.engagementScore, 0) / members.length);
  }, [members]);

  return (
    <div className="p-8 space-y-8 overflow-y-auto h-full bg-slate-50/50">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {[
          { label: 'Total de Registros', value: members.length, icon: <Users />, color: 'text-indigo-600', bg: 'bg-indigo-50' },
          { label: 'Taxa de Atividade', value: `${activeRate}%`, icon: <Activity />, color: 'text-emerald-600', bg: 'bg-emerald-50' },
          { label: 'Score Engajamento', value: `${avgEngagement}%`, icon: <Target />, color: 'text-blue-600', bg: 'bg-blue-50' },
          { label: 'Evasão (Estatística)', value: '12%', icon: <AlertTriangle />, color: 'text-amber-600', bg: 'bg-amber-50' },
        ].map((stat, i) => (
          <div key={i} className="bg-white p-6 rounded-[32px] shadow-sm border border-slate-100 flex items-center justify-between transition-all hover:shadow-md">
            <div>
              <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">{stat.label}</p>
              <h3 className="text-3xl font-black text-slate-800 mt-1">{stat.value}</h3>
            </div>
            <div className={`p-4 rounded-2xl ${stat.bg} ${stat.color}`}>
              {React.cloneElement(stat.icon as React.ReactElement, { className: 'w-7 h-7' })}
            </div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white p-8 rounded-[40px] shadow-sm border border-slate-100">
          <div className="flex justify-between items-center mb-8">
            <div>
               <h3 className="text-xl font-black text-slate-800">Check-ins na Semana</h3>
               <p className="text-xs text-slate-400 font-medium">Volume de registros processados por dia</p>
            </div>
          </div>
          <div className="h-72">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={growthData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11, fontWeight: 'bold'}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 10px 25px rgba(0,0,0,0.05)', padding: '12px'}}
                />
                <Bar dataKey="count" fill="#6366f1" radius={[8, 8, 0, 0]} barSize={40} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[40px] shadow-sm border border-slate-100 flex flex-col">
          <h3 className="text-xl font-black text-slate-800 mb-2">Distribuição de Membros</h3>
          <p className="text-xs text-slate-400 font-medium mb-8">Proporção por estágio da jornada</p>
          <div className="flex-1 min-h-[250px]">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={stageData}
                  cx="50%"
                  cy="50%"
                  innerRadius={70}
                  outerRadius={100}
                  paddingAngle={8}
                  dataKey="value"
                >
                  {stageData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="mt-6 grid grid-cols-2 gap-3 pt-6 border-t border-slate-50">
            {stageData.map((s, i) => (
              <div key={i} className="flex items-center gap-2">
                <div className="w-2.5 h-2.5 rounded-full" style={{backgroundColor: COLORS[i]}} />
                <span className="text-[10px] text-slate-500 font-bold uppercase truncate">{s.name}: {s.value}</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 pb-8">
        <div className="bg-white p-8 rounded-[40px] shadow-sm border border-slate-100">
           <div className="mb-8">
              <h3 className="text-xl font-black text-slate-800">Conversão por Estágio</h3>
              <p className="text-xs text-slate-400 font-medium">Eficiência na transição de membros</p>
           </div>
          <div className="space-y-6">
            {[
              { label: 'Visitante ➔ Novo Membro', val: 75 },
              { label: 'Novo Membro ➔ Ativo', val: 62 },
              { label: 'Ativo ➔ Líder Treino', val: 40 },
              { label: 'Treino ➔ Líder', val: 95 },
            ].map((item, i) => (
              <div key={i} className="space-y-2">
                <div className="flex justify-between text-xs font-bold uppercase tracking-tighter">
                  <span className="text-slate-500">{item.label}</span>
                  <span className="text-indigo-600">{item.val}%</span>
                </div>
                <div className="w-full h-3 bg-slate-50 rounded-full overflow-hidden p-0.5 border border-slate-100">
                  <div 
                    className="h-full rounded-full bg-gradient-to-r from-indigo-400 to-indigo-600 transition-all duration-1000" 
                    style={{width: `${item.val}%`}}
                  />
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="bg-white p-8 rounded-[40px] shadow-sm border border-slate-100">
          <h3 className="text-xl font-black text-slate-800 mb-8">Mentoria de Liderança</h3>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="text-slate-400 border-b border-slate-50 uppercase text-[10px] font-black">
                  <th className="text-left pb-4">Responsável</th>
                  <th className="text-left pb-4">Membros</th>
                  <th className="text-right pb-4">Performance</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {Array.from(new Set(members.map(m => m.responsibleLeader).filter(Boolean))).map((leader, i) => (
                  <tr key={i} className="group hover:bg-slate-50/50 transition-colors">
                    <td className="py-4 font-bold text-slate-700">{leader}</td>
                    <td className="py-4 text-slate-500 font-medium">
                       {members.filter(m => m.responsibleLeader === leader).length} acompanhados
                    </td>
                    <td className="py-4 text-right">
                      <div className="inline-flex items-center gap-1.5 px-3 py-1 bg-emerald-50 text-emerald-600 rounded-full text-[10px] font-black uppercase">
                        <TrendingUp className="w-3 h-3" /> Alta
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
            {members.every(m => !m.responsibleLeader) && (
              <div className="py-10 text-center text-slate-400 text-xs italic">Nenhuma mentoria ativa atribuída.</div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default AnalyticsDashboard;

export enum MemberStage {
  VISITOR = 'VISITOR',
  NEW_MEMBER = 'NEW_MEMBER',
  ACTIVE_MEMBER = 'ACTIVE_MEMBER',
  LEADER_IN_TRAINING = 'LEADER_IN_TRAINING',
  LEADER = 'LEADER'
}

export enum UserRole {
  ADMIN = 'ADMIN',
  PASTOR = 'PASTOR',
  LEADER = 'LEADER',
  VOLUNTEER = 'VOLUNTEER'
}

export interface SystemUser {
  id: string;
  name: string;
  email: string;
  whatsapp?: string;
  role: UserRole;
  church: string;
  avatar?: string;
  permissions: string[];
}

export interface Member {
  id: string;
  name: string;
  email: string;
  phone: string;
  gender?: string;
  religion?: string;
  address?: string;
  stage: MemberStage;
  lastActivity: Date;
  engagementScore: number; // 0-100
  assignedLeaderId?: string;
  registrationDate: Date;
  channel: string;
  interests?: string[];
  responsibleLeader?: string;
}

export interface AnalyticsData {
  stageDistribution: { name: string; value: number }[];
  retentionRate: number;
  conversionTime: string; // Average time to next stage
  weeklyGrowth: { day: string; count: number }[];
}

export interface AutomationRule {
  id: string;
  name: string;
  trigger: string;
  action: string;
  isActive: boolean;
}

