  Lock
} from 'lucide-react';
import KanbanBoard from './components/KanbanBoard';
import AnalyticsDashboard from './components/AnalyticsDashboard';
import AutomationSettings from './components/AutomationSettings';
import { INITIAL_MEMBERS, INTEGRATIONS, STAGES } from './constants';
import { Member, MemberStage, SystemUser, UserRole } from './types';

const TIMEZONES = [
  "(GMT-03:00) Brasília / São Paulo",
  "(GMT-04:00) Manaus / Campo Grande",
  "(GMT-05:00) Rio Branco",
  "(GMT-00:00) London / Lisbon",
  "(GMT+01:00) Paris / Berlin",
  "(GMT-05:00) New York / Miami"
];

const AVAILABLE_PERMISSIONS = [
  { id: 'view_dashboard', label: 'Ver Dashboard' },
  { id: 'manage_pipeline', label: 'Gerir Pipeline' },
  { id: 'manage_contacts', label: 'Gerir Contatos' },
  { id: 'manage_team', label: 'Gerir Equipe' },
  { id: 'manage_church', label: 'Configurar Igreja' },
  { id: 'manage_settings', label: 'Acesso às Configurações' }
];

const App: React.FC = () => {
  const [theme, setTheme] = useState<'light' | 'dark'>('light');
  const [viewMode, setViewMode] = useState<'blocks' | 'list'>('list');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentUser, setCurrentUser] = useState<SystemUser | null>(null);
  const [teamMembers, setTeamMembers] = useState<SystemUser[]>([]);
  const [members, setMembers] = useState<Member[]>(INITIAL_MEMBERS);
  const [activeTab, setActiveTab] = useState<'kanban' | 'analytics' | 'automation' | 'team' | 'church' | 'contacts' | 'settings'>('kanban');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [churchData, setChurchData] = useState({ logo: '', name: '', cep: '', address: '', city: '', state: '', pastor: '' });
  const [timezone, setTimezone] = useState(TIMEZONES[0]);

  // Modal states
  const [isMemberModalOpen, setIsMemberModalOpen] = useState(false);
  const [editingMember, setEditingMember] = useState<Partial<Member> | null>(null);
  const [isTeamModalOpen, setIsTeamModalOpen] = useState(false);
  const [editingTeamMember, setEditingTeamMember] = useState<Partial<SystemUser> | null>(null);
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);

  const [loginForm, setLoginForm] = useState({ name: '', email: '', whatsapp: '', church: '', password: '' });

  const moveMember = (id: string, nextStage: MemberStage) => {
    setMembers(prev => prev.map(m => m.id === id ? { ...m, stage: nextStage } : m));
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const newUser: SystemUser = {
      id: Math.random().toString(36).substr(2, 9),
      name: loginForm.name || 'Usuário Koinonia',
      email: loginForm.email || 'usuario@koinonia.com',
      whatsapp: loginForm.whatsapp,
      role: UserRole.ADMIN,
      church: loginForm.church || 'Igreja Central',
      permissions: AVAILABLE_PERMISSIONS.map(p => p.id),
      avatar: 'https://picsum.photos/id/64/100/100'
    };
    setCurrentUser(newUser);
    setTeamMembers([newUser]); 
    setChurchData(prev => ({ ...prev, name: newUser.church, pastor: newUser.name }));
    setIsLoggedIn(true);
  };

  const handleSaveMember = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingMember?.name) return;
    if (editingMember.id) {
      setMembers(prev => prev.map(m => m.id === editingMember.id ? (editingMember as Member) : m));
    } else {
      const newMember: Member = {
        ...(editingMember as Member),
        id: Math.random().toString(36).substr(2, 9),
        channel: editingMember.channel || 'MANUAL'
      };
      setMembers(prev => [...prev, newMember]);
    }
    setIsMemberModalOpen(false);
  };

  const handleSaveTeamMember = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingTeamMember?.name) return;
    if (editingTeamMember.id) {
      setTeamMembers(prev => prev.map(u => u.id === editingTeamMember.id ? (editingTeamMember as SystemUser) : u));
    } else {
      const newUser: SystemUser = {
        ...(editingTeamMember as SystemUser),
        id: Math.random().toString(36).substr(2, 9),
        permissions: editingTeamMember.permissions || []
      };
      setTeamMembers(prev => [...prev, newUser]);
    }
    setIsTeamModalOpen(false);
  };

  const updateCurrentUser = (e: React.FormEvent) => {
    e.preventDefault();
    if (currentUser) {
      setTeamMembers(prev => prev.map(u => u.id === currentUser.id ? currentUser : u));
      alert("Perfil atualizado com sucesso!");
    }
  };

  const renderMemberListView = () => (
    <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden mx-6 mb-6 flex-1 flex flex-col">
      <div className="overflow-y-auto">
        <table className="w-full text-sm text-left">
          <thead className="bg-slate-50 text-slate-500 uppercase text-[10px] font-bold sticky top-0">
            <tr>
              <th className="px-6 py-4">Membro</th>
              <th className="px-6 py-4">WhatsApp</th>
              <th className="px-6 py-4">Estágio</th>
              <th className="px-6 py-4">Religião / Sexo</th>
              <th className="px-6 py-4 text-right">Ações</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {members.map(member => (
              <tr key={member.id} className="hover:bg-slate-50 transition-colors group cursor-pointer" onClick={() => { setEditingMember(member); setIsMemberModalOpen(true); }}>
                <td className="px-6 py-4">
                  <p className="font-bold text-slate-800">{member.name}</p>
                  <p className="text-xs text-slate-400 truncate max-w-[150px]">{member.address || member.email}</p>
                </td>
                <td className="px-6 py-4 text-slate-600 font-medium">{member.phone}</td>
                <td className="px-6 py-4">
                  <span className={`px-2 py-1 rounded-full text-[10px] font-bold uppercase ${STAGES.find(s => s.id === member.stage)?.color}`}>
                    {STAGES.find(s => s.id === member.stage)?.label}
                  </span>
                </td>
                <td className="px-6 py-4">
                  <div className="flex flex-col">
                    <span className="text-slate-700 font-medium">{member.religion || 'Não inf.'}</span>
                    <span className="text-[10px] text-slate-400 font-bold uppercase">{member.gender || '-'}</span>
                  </div>
                </td>
                <td className="px-6 py-4 text-right">
                  <div className="flex justify-end gap-2">
                    <button className="p-2 text-slate-400 hover:text-indigo-600 rounded-lg"><Edit2 className="w-4 h-4" /></button>
                    <button onClick={(e) => { e.stopPropagation(); setMembers(members.filter(m => m.id !== member.id)); }} className="p-2 text-slate-400 hover:text-red-600 rounded-lg"><Trash2 className="w-4 h-4" /></button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );

  return (
    <div className={`flex h-screen overflow-hidden ${theme === 'dark' ? 'bg-slate-950 text-slate-100' : 'bg-slate-50 text-slate-800'}`}>
      <aside className={`${theme === 'dark' ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'} border-r transition-all duration-300 flex flex-col ${isSidebarOpen ? 'w-64' : 'w-20'}`}>
        <div className="p-6 flex items-center gap-3">
          <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white font-bold text-xl shadow-lg shadow-indigo-200">K</div>
          {isSidebarOpen && <div className="flex flex-col"><span className={`font-bold leading-tight ${theme === 'dark' ? 'text-white' : 'text-slate-800'}`}>Koinonia</span><span className="text-[10px] text-slate-400 uppercase font-bold tracking-tighter">Growth CRM</span></div>}
        </div>
        <nav className="flex-1 mt-6 px-3 space-y-1 overflow-y-auto">
          {navItems.map((item) => (
            <button key={item.id} onClick={() => setActiveTab(item.id as any)} className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl transition-all ${activeTab === item.id ? 'bg-indigo-50 text-indigo-700 font-semibold' : 'text-slate-500 hover:bg-slate-50 hover:text-slate-800'}`}>
              <div className={activeTab === item.id ? 'text-indigo-600' : 'text-slate-400'}>{item.icon}</div>
              {isSidebarOpen && <span>{item.label}</span>}
              {activeTab === item.id && isSidebarOpen && <ChevronRight className="w-4 h-4 ml-auto" />}
            </button>
          ))}
        </nav>
        <div className="p-4 mt-auto border-t border-slate-100">
          <button onClick={() => setIsLoggedIn(false)} className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl text-slate-500 hover:bg-red-50 hover:text-red-600 transition-all`}><LogOut className="w-5 h-5" />{isSidebarOpen && <span>Sair</span>}</button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden">
        <header className={`${theme === 'dark' ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'} h-16 border-b px-6 flex items-center justify-between z-20`}>
          <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 hover:bg-slate-50 rounded-lg text-slate-400">{isSidebarOpen ? <X className="w-5 h-5" /> : <Menu className="w-5 h-5" />}</button>
            <div className="hidden md:flex items-center bg-slate-100 px-3 py-1.5 rounded-xl border border-slate-200">
              <Search className="w-4 h-4 text-slate-400" />
              <input type="text" placeholder="Buscar..." className="bg-transparent border-none focus:ring-0 text-sm w-64 placeholder-slate-400 ml-2 text-slate-800" />
            </div>
          </div>
          <div className="flex items-center gap-4">
            <button className="relative p-2 text-slate-400 hover:bg-slate-50 rounded-lg"><Bell className="w-5 h-5" /><span className="absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full border-2 border-white"></span></button>
            <div className="h-8 w-px bg-slate-200 mx-1"></div>
            <div className="relative">
              <button onClick={() => setIsProfileOpen(!isProfileOpen)} className="flex items-center gap-3 pl-2 py-1 px-2 rounded-xl hover:bg-slate-50 transition-all">
                <div className="text-right hidden sm:block"><p className={`text-sm font-bold leading-none ${theme === 'dark' ? 'text-white' : 'text-slate-800'}`}>{currentUser?.name}</p><p className="text-[10px] text-slate-400 font-bold uppercase mt-1">{currentUser?.role}</p></div>
                <div className="w-10 h-10 rounded-full bg-blue-50 flex items-center justify-center text-blue-600 border border-blue-100 font-bold text-sm">{currentUser?.name?.[0]}</div>
              </button>
              {isProfileOpen && (
                <div className="absolute right-0 mt-2 w-72 bg-white rounded-2xl shadow-2xl border border-slate-100 overflow-hidden animate-in fade-in slide-in-from-top-2">
                  <div className="p-4 border-b border-slate-100 bg-slate-50/50"><div className="flex items-center gap-3"><div className="w-10 h-10 rounded-full bg-blue-100 flex items-center justify-center text-blue-700 font-bold">{currentUser?.name?.[0]}</div><div className="overflow-hidden"><p className="text-sm font-bold text-slate-800 truncate">{currentUser?.name}</p><p className="text-xs text-slate-500 truncate">{currentUser?.email}</p></div></div></div>
                  <div className="p-2">
                    <button onClick={() => {setActiveTab('settings'); setIsProfileOpen(false)}} className="w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-slate-700 hover:bg-slate-50 text-sm"><User className="w-4 h-4 text-slate-400" /> Meu perfil</button>
                    <button onClick={() => {setActiveTab('settings'); setIsProfileOpen(false)}} className="w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-slate-700 hover:bg-slate-50 text-sm"><Settings className="w-4 h-4 text-slate-400" /> Configurações</button>
                  </div>
                  <div className="p-2 border-t border-slate-100"><button onClick={() => setIsLoggedIn(false)} className="w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-red-600 hover:bg-red-50 text-sm"><LogOut className="w-4 h-4" /> Sair</button></div>
                </div>
              )}
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-hidden relative">
          {activeTab === 'kanban' && <KanbanBoard members={members} onMoveMember={moveMember} onAddMember={() => { setEditingMember({ stage: MemberStage.VISITOR, interests: [], channel: 'MANUAL' }); setIsMemberModalOpen(true); }} onMemberClick={(m) => { setEditingMember(m); setIsMemberModalOpen(true); }} />}
          {activeTab === 'analytics' && <AnalyticsDashboard members={members} />}
          {activeTab === 'automation' && <AutomationSettings />}

          {activeTab === 'team' && (
            <div className="p-8 h-full overflow-y-auto">
              <div className="flex justify-between items-center mb-8">
                <div><h2 className="text-2xl font-bold text-slate-800">Equipe de Liderança</h2><p className="text-slate-500">Gestão de líderes e permissões granulares.</p></div>
                <button onClick={() => { setEditingTeamMember({ role: UserRole.LEADER, permissions: [] }); setIsTeamModalOpen(true); }} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-xl font-bold hover:bg-indigo-700 shadow-lg shadow-indigo-100"><UserPlus className="w-4 h-4" /> Novo Líder</button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {teamMembers.map((member) => (
                  <div key={member.id} className="bg-white p-6 rounded-[32px] border border-slate-100 shadow-sm hover:shadow-md transition-all relative group">
                    <div className="flex items-center gap-4 mb-4"><div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center text-indigo-600 font-bold border border-indigo-100">{member.name[0]}</div><div><h4 className="font-bold text-slate-800">{member.name}</h4><p className="text-xs text-indigo-600 font-bold uppercase">{member.role}</p></div></div>
                    <div className="space-y-2 text-sm text-slate-500 border-t pt-4">
                      <div className="flex justify-between"><span>WhatsApp</span><span className="font-bold text-slate-700">{member.whatsapp || '-'}</span></div>
                      <div className="flex flex-wrap gap-1 mt-2">{member.permissions.slice(0, 3).map(p => <span key={p} className="text-[9px] bg-slate-100 px-2 py-0.5 rounded-full font-bold text-slate-400 uppercase">{p.split('_')[1]}</span>)}</div>
                    </div>
                    <div className="absolute top-4 right-4 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity"><button onClick={() => { setEditingTeamMember(member); setIsTeamModalOpen(true); }} className="p-1.5 bg-slate-50 text-slate-400 hover:text-indigo-600 rounded-lg"><Edit2 className="w-3.5 h-3.5" /></button><button onClick={() => setTeamMembers(teamMembers.filter(u => u.id !== member.id))} className="p-1.5 bg-slate-50 text-slate-400 hover:text-red-600 rounded-lg"><Trash2 className="w-3.5 h-3.5" /></button></div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {activeTab === 'contacts' && (
            <div className="h-full flex flex-col overflow-hidden">
               <div className="flex justify-between items-center p-6 border-b border-slate-100 bg-white z-10"><div><h2 className="text-2xl font-bold text-slate-800">Contatos Koinonia</h2><p className="text-xs text-slate-400 font-medium uppercase">Registro unificado e histórico de membros</p></div><div className="flex gap-2"><div className="bg-slate-100 p-1 rounded-xl flex gap-1"><button onClick={() => setViewMode('list')} className={`p-1.5 rounded-lg transition-all ${viewMode === 'list' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}><List className="w-5 h-5" /></button><button onClick={() => setViewMode('blocks')} className={`p-1.5 rounded-lg transition-all ${viewMode === 'blocks' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}><LayoutGrid className="w-5 h-5" /></button></div><button onClick={() => setIsImportModalOpen(true)} className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-200 text-slate-600 rounded-xl font-bold hover:bg-slate-50"><Upload className="w-4 h-4" /> Importar CSV</button><button className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-xl font-bold hover:bg-indigo-700 shadow-lg" onClick={() => { setEditingMember({ stage: MemberStage.VISITOR, interests: [], channel: 'MANUAL' }); setIsMemberModalOpen(true); }}><Plus className="w-4 h-4" /> Novo Contato</button></div></div>
               <div className="flex-1 overflow-hidden">{viewMode === 'list' ? renderMemberListView() : <div className="p-6 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 overflow-y-auto h-full">{members.map(m => ( <div key={m.id} onClick={() => { setEditingMember(m); setIsMemberModalOpen(true); }} className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm hover:shadow-md transition-all cursor-pointer"> <div className="flex justify-between mb-3"><div className="w-10 h-10 rounded-2xl bg-indigo-50 flex items-center justify-center text-indigo-600 font-bold">{m.name[0]}</div><span className="text-[9px] font-bold uppercase bg-slate-100 px-2 py-1 rounded-lg text-slate-400">{m.religion}</span></div><h4 className="font-bold text-slate-800 truncate">{m.name}</h4><p className="text-xs text-slate-400 truncate mb-4">{m.phone}</p><div className="flex justify-between items-center pt-4 border-t border-slate-50"><span className="text-[10px] font-bold text-slate-300 uppercase">{m.gender}</span><ChevronRight className="w-4 h-4 text-slate-200" /></div></div> ))}</div>}</div>
            </div>
          )}

          {activeTab === 'settings' && (
            <div className="p-8 h-full overflow-y-auto space-y-8 max-w-4xl mx-auto">
              <h2 className="text-3xl font-bold text-slate-800">Ajustes da Conta</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <section className="bg-white p-8 rounded-[40px] border border-slate-100 shadow-sm space-y-6">
                  <h3 className="font-bold text-slate-800 flex items-center gap-2"><User className="w-5 h-5 text-indigo-500" /> Meu Perfil</h3>
                  <form onSubmit={updateCurrentUser} className="space-y-4">
                    <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">Nome</label><input value={currentUser?.name || ''} onChange={e => setCurrentUser(prev => prev ? {...prev, name: e.target.value} : null)} className="w-full p-3 bg-slate-50 rounded-xl outline-none font-bold text-slate-700 border-none" /></div>
                    <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">WhatsApp</label><input value={currentUser?.whatsapp || ''} onChange={e => setCurrentUser(prev => prev ? {...prev, whatsapp: e.target.value} : null)} className="w-full p-3 bg-slate-50 rounded-xl outline-none text-slate-700 border-none" /></div>
                    <button type="submit" className="w-full py-3 bg-indigo-600 text-white font-bold rounded-xl shadow-lg shadow-indigo-100">Atualizar Perfil</button>
                  </form>
                </section>
                <section className="bg-white p-8 rounded-[40px] border border-slate-100 shadow-sm space-y-6">
                  <h3 className="font-bold text-slate-800 flex items-center gap-2"><Globe className="w-5 h-5 text-blue-500" /> Sistema & Regional</h3>
                  <div className="space-y-4">
                    <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">Fuso Horário</label><select value={timezone} onChange={e => setTimezone(e.target.value)} className="w-full p-3 bg-slate-50 rounded-xl outline-none text-sm font-bold text-slate-700 border-none">{TIMEZONES.map(t => <option key={t} value={t}>{t}</option>)}</select></div>
                    <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">Aparência</label><div className="flex gap-2"><button onClick={() => setTheme('light')} className={`flex-1 p-3 rounded-xl border-2 transition-all ${theme === 'light' ? 'bg-indigo-50 border-indigo-600 text-indigo-700' : 'bg-white border-slate-100 text-slate-400'}`}>Claro</button><button onClick={() => setTheme('dark')} className={`flex-1 p-3 rounded-xl border-2 transition-all ${theme === 'dark' ? 'bg-slate-800 border-slate-700 text-white' : 'bg-white border-slate-100 text-slate-400'}`}>Escuro</button></div></div>
                  </div>
                </section>
                <section className="bg-white p-8 rounded-[40px] border border-slate-100 shadow-sm col-span-1 md:col-span-2 space-y-6">
                  <h3 className="font-bold text-slate-800 flex items-center gap-2"><Bell className="w-5 h-5 text-amber-500" /> Central de Notificações</h3>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl"><div><p className="text-sm font-bold text-slate-700">Notificações Push</p><p className="text-[10px] text-slate-400 font-medium">Alertas em tempo real no desktop</p></div><input type="checkbox" className="w-5 h-5 rounded text-indigo-600" defaultChecked /></div>
                    <div className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl"><div><p className="text-sm font-bold text-slate-700">Relatórios por E-mail</p><p className="text-[10px] text-slate-400 font-medium">Sumário semanal de crescimento</p></div><input type="checkbox" className="w-5 h-5 rounded text-indigo-600" /></div>
                  </div>
                </section>
              </div>
            </div>
          )}
        </div>
      </main>

      {/* Member Modal */}
      {isMemberModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[40px] w-full max-w-3xl shadow-2xl overflow-hidden animate-in zoom-in duration-300">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-indigo-600 text-white">
              <div><h3 className="text-2xl font-bold">{editingMember?.id ? 'Editar Contato' : 'Nova Ficha Koinonia'}</h3><p className="text-xs text-indigo-100 uppercase font-black tracking-widest mt-1">Dados de Integração e Jornada</p></div>
              <button onClick={() => setIsMemberModalOpen(false)} className="p-2 hover:bg-white/20 rounded-xl transition-all"><X className="w-6 h-6" /></button>
            </div>
            <form onSubmit={handleSaveMember} className="p-8 space-y-6 overflow-y-auto max-h-[75vh] scrollbar-hide">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">Nome Completo</label><input required value={editingMember?.name || ''} onChange={e => setEditingMember({...editingMember, name: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl font-bold text-slate-800" /></div>
                <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">WhatsApp</label><input required value={editingMember?.phone || ''} onChange={e => setEditingMember({...editingMember, phone: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl text-slate-800" /></div>
                <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">Sexo</label><select value={editingMember?.gender || ''} onChange={e => setEditingMember({...editingMember, gender: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl font-bold text-slate-700"><option value="">Selecione</option><option value="Masculino">Masculino</option><option value="Feminino">Feminino</option><option value="Outro">Outro</option></select></div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">Religião / Antecedente</label><input value={editingMember?.religion || ''} onChange={e => setEditingMember({...editingMember, religion: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl text-slate-800" placeholder="Ex: Católico, Evangélico, Sem religião" /></div>
                <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">Canal (Origem)</label><input value={editingMember?.channel || ''} onChange={e => setEditingMember({...editingMember, channel: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl font-bold text-slate-800" placeholder="Ex: Instagram, Amigo, Volante" /></div>
              </div>
              <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">Endereço Residencial Completo</label><input value={editingMember?.address || ''} onChange={e => setEditingMember({...editingMember, address: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl text-slate-800" placeholder="Rua, Número, Bairro, Cidade - Estado" /></div>
              <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">Interesses (Separar por vírgula para novos)</label><div className="flex flex-wrap gap-2 mb-2">{['Música', 'Célula', 'Infantil', 'Jovens'].map(tag => ( <button type="button" key={tag} onClick={() => { const current = editingMember?.interests || []; const next = current.includes(tag) ? current.filter(t => t !== tag) : [...current, tag]; setEditingMember({...editingMember, interests: next}); }} className={`px-3 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all ${editingMember?.interests?.includes(tag) ? 'bg-indigo-600 text-white shadow-md' : 'bg-slate-100 text-slate-400'}`}>{tag}</button> ))}</div><input value={editingMember?.interests?.join(', ') || ''} onChange={e => setEditingMember({...editingMember, interests: e.target.value.split(',').map(s => s.trim())})} className="w-full p-3 bg-slate-50 rounded-xl text-xs text-slate-600 italic" placeholder="Ou digite novos interesses aqui..." /></div>
              <div className="pt-8 border-t flex justify-between gap-4"><button type="button" onClick={() => setIsMemberModalOpen(false)} className="px-8 py-3 text-slate-400 font-bold hover:bg-slate-50 rounded-xl transition-all">Descartar</button><button type="submit" className="px-12 py-3 bg-indigo-600 text-white font-black rounded-xl shadow-xl shadow-indigo-100 uppercase tracking-widest text-xs active:scale-95 transition-all">Salvar Registro</button></div>
            </form>
          </div>
        </div>
      )}

      {/* Team Member Modal */}
      {isTeamModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[40px] w-full max-w-lg shadow-2xl overflow-hidden animate-in slide-in-from-bottom duration-300">
            <div className="p-8 border-b border-slate-100 bg-indigo-600 text-white flex justify-between items-center"><h3 className="text-xl font-bold">Gerir Líder da Equipe</h3><button onClick={() => setIsTeamModalOpen(false)} className="p-2 hover:bg-white/20 rounded-xl transition-all"><X className="w-5 h-5" /></button></div>
            <form onSubmit={handleSaveTeamMember} className="p-8 space-y-4">
              <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">Nome do Líder</label><input required value={editingTeamMember?.name || ''} onChange={e => setEditingTeamMember({...editingTeamMember, name: e.target.value})} className="w-full p-3 bg-slate-100 rounded-xl font-bold text-slate-800" /></div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">Email Corporativo</label><input type="email" value={editingTeamMember?.email || ''} onChange={e => setEditingTeamMember({...editingTeamMember, email: e.target.value})} className="w-full p-3 bg-slate-100 rounded-xl text-slate-700 text-sm" /></div>
                <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">WhatsApp</label><input required value={editingTeamMember?.whatsapp || ''} onChange={e => setEditingTeamMember({...editingTeamMember, whatsapp: e.target.value})} className="w-full p-3 bg-slate-100 rounded-xl font-bold text-indigo-600 text-sm" /></div>
              </div>
              <div className="space-y-3 pt-4 border-t border-slate-50"><label className="text-[10px] font-black text-slate-400 uppercase flex items-center gap-2"><Lock className="w-3 h-3" /> Permissões de Acesso</label><div className="grid grid-cols-2 gap-2">{AVAILABLE_PERMISSIONS.map(p => ( <label key={p.id} className="flex items-center gap-2 p-2 bg-slate-50 rounded-lg cursor-pointer hover:bg-slate-100 transition-colors"> <input type="checkbox" checked={editingTeamMember?.permissions?.includes(p.id)} onChange={e => { const current = editingTeamMember?.permissions || []; const next = e.target.checked ? [...current, p.id] : current.filter(id => id !== p.id); setEditingTeamMember({...editingTeamMember, permissions: next}); }} className="rounded text-indigo-600" /> <span className="text-[10px] font-bold text-slate-600 uppercase">{p.label}</span> </label> ))}</div></div>
              <button type="submit" className="w-full py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl mt-6 active:scale-95 transition-all">Atualizar Membro de Equipe</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

const navItems = [
  { id: 'kanban', label: 'Pipeline', icon: <Columns className="w-5 h-5" /> },
  { id: 'contacts', label: 'Contatos', icon: <ContactIcon className="w-5 h-5" /> },
  { id: 'analytics', label: 'Dashboard', icon: <LayoutDashboard className="w-5 h-5" /> },
  { id: 'team', label: 'Equipe', icon: <UsersIcon className="w-5 h-5" /> },
  { id: 'church', label: 'Igreja', icon: <ChurchIcon className="w-5 h-5" /> },
  { id: 'automation', label: 'Automação', icon: <Zap className="w-5 h-5" /> },
  { id: 'settings', label: 'Configurações', icon: <Settings className="w-5 h-5" /> },
];

export default App;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Columns, 
  Zap, 
  Settings, 
  Bell, 
  Search, 
  User,
  LogOut,
  ChevronRight,
  Menu,
  X,
  Save,
  Trash2,
  Users as UsersIcon,
  Church as ChurchIcon,
  Contact as ContactIcon,
  CheckCircle,
  Plus,
  ArrowRight,
  Key,
  Globe,
  Palette,
  Clock,
  HelpCircle,
  ShieldCheck,
  Smartphone,
  List,
  LayoutGrid,
  MapPin,
  Upload,
  UserPlus,
  Edit2,
  Lock
} from 'lucide-react';
import KanbanBoard from './components/KanbanBoard';
