            <input required type="email" placeholder="E-mail" className="w-full px-4 py-3 bg-slate-100 rounded-2xl outline-none text-slate-800" value={loginForm.email} onChange={e => setLoginForm({...loginForm, email: e.target.value})} />
            <input required placeholder="Sua Igreja" className="w-full px-4 py-3 bg-slate-100 rounded-2xl outline-none text-slate-800" value={loginForm.church} onChange={e => setLoginForm({...loginForm, church: e.target.value})} />
            <input required type="password" placeholder="Criar Senha" className="w-full px-4 py-3 bg-slate-100 rounded-2xl outline-none text-slate-800" value={loginForm.password} onChange={e => setLoginForm({...loginForm, password: e.target.value})} />
