              <div className="w-10 h-10 rounded-full bg-blue-50 flex items-center justify-center text-blue-600 border border-blue-100 font-bold text-sm">{currentUser?.name?.[0]}</div>
            </button>
            {isProfileOpen && (
              <div className="absolute right-6 top-14 w-72 bg-white rounded-2xl shadow-2xl border border-slate-100 overflow-hidden z-[100] animate-in fade-in slide-in-from-top-2">
                <div className="p-4 border-b border-slate-100 bg-slate-50/50 flex items-center gap-3"><div className="w-10 h-10 rounded-full bg-blue-100 flex items-center justify-center text-blue-700 font-bold">{currentUser?.name?.[0]}</div><div className="overflow-hidden"><p className="text-sm font-bold text-slate-800 truncate">{currentUser?.name}</p><p className="text-xs text-slate-500 truncate">{currentUser?.email}</p></div></div>
                <div className="p-2"><button onClick={() => {setActiveTab('settings'); setIsProfileOpen(false)}} className="w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-slate-700 hover:bg-slate-50 text-sm"><User className="w-4 h-4 text-slate-400" /> Meu perfil</button></div>
                <div className="p-2 border-t border-slate-100"><button onClick={() => setIsLoggedIn(false)} className="w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-red-600 hover:bg-red-50 text-sm"><LogOut className="w-4 h-4" /> Sair</button></div>
              </div>
            )}
          </div>
        </header>

        <div className="flex-1 overflow-hidden relative">
          {activeTab === 'kanban' && <KanbanBoard members={members} onMoveMember={moveMember} onAddMember={() => { setEditingMember({ stage: MemberStage.VISITOR, interests: [], channel: 'MANUAL' }); setIsMemberModalOpen(true); }} onMemberClick={(m) => { setEditingMember(m); setIsMemberModalOpen(true); }} />}
          {activeTab === 'analytics' && <AnalyticsDashboard members={members} />}
          {activeTab === 'automation' && <AutomationSettings />}

          {activeTab === 'team' && (
            <div className="p-8 h-full overflow-y-auto">
              <div className="flex justify-between items-center mb-8">
                <div><h2 className="text-2xl font-bold text-slate-800">Equipe de Liderança</h2><p className="text-slate-500">Gestão de líderes e permissões de acesso.</p></div>
                <button onClick={() => { setEditingTeamMember({ role: UserRole.LEADER, permissions: [] }); setIsTeamModalOpen(true); }} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-xl font-bold hover:bg-indigo-700 shadow-lg"><UserPlus className="w-4 h-4" /> Novo Líder</button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {teamMembers.map(member => (
                  <div key={member.id} className="bg-white p-6 rounded-[32px] border border-slate-100 shadow-sm relative group">
                    <div className="flex items-center gap-4 mb-4"><div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center text-indigo-600 font-bold border border-indigo-100">{member.name[0]}</div><div><h4 className="font-bold text-slate-800">{member.name}</h4><p className="text-xs text-indigo-600 font-bold uppercase">{member.role}</p></div></div>
                    <div className="space-y-2 text-sm text-slate-500 border-t pt-4">
                      <div className="flex justify-between"><span>WhatsApp</span><span className="font-bold text-slate-700">{member.whatsapp || '-'}</span></div>
                      <div className="flex flex-wrap gap-1 mt-2">{member.permissions.map(p => <span key={p} className="text-[9px] bg-slate-100 px-2 py-0.5 rounded-full font-bold text-slate-400 uppercase">{p.split('_')[1]}</span>)}</div>
                    </div>
                    <div className="absolute top-4 right-4 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity"><button onClick={() => { setEditingTeamMember(member); setIsTeamModalOpen(true); }} className="p-1.5 bg-slate-50 text-slate-400 hover:text-indigo-600 rounded-lg"><Edit2 className="w-3.5 h-3.5" /></button><button onClick={() => handleDeleteTeamMember(member.id)} className="p-1.5 bg-slate-50 text-slate-400 hover:text-red-600 rounded-lg"><Trash2 className="w-3.5 h-3.5" /></button></div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {activeTab === 'church' && (
            <div className="p-8 h-full overflow-y-auto max-w-2xl mx-auto">
              <h2 className="text-2xl font-bold text-slate-800 mb-8 text-center">Configurações da Igreja</h2>
              <div className="space-y-6 bg-white p-8 rounded-[40px] border border-slate-100 shadow-sm">
                <div className="flex flex-col items-center gap-4 mb-6">
                  <div className="w-32 h-32 bg-slate-50 rounded-[32px] border-2 border-dashed border-slate-200 flex flex-col items-center justify-center text-slate-400 relative overflow-hidden group">
                    {churchData.logo ? <img src={churchData.logo} className="w-full h-full object-cover" /> : <Upload className="w-8 h-8 group-hover:text-indigo-500 transition-colors" />}
                  </div>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-1"><label className="text-xs font-bold text-slate-400 uppercase ml-1">Nome da Igreja</label><input value={churchData.name} onChange={e => setChurchData({...churchData, name: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl outline-none text-slate-800 font-bold border-none" /></div>
                  <div className="space-y-1"><label className="text-xs font-bold text-slate-400 uppercase ml-1">Pastor Titular</label><select value={churchData.pastor} onChange={e => setChurchData({...churchData, pastor: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl outline-none text-slate-800 border-none">{teamMembers.map(u => <option key={u.id} value={u.name}>{u.name}</option>)}</select></div>
                </div>
                <div className="grid grid-cols-3 gap-4">
                  <div className="space-y-1"><label className="text-xs font-bold text-slate-400 uppercase ml-1">CEP</label><input value={churchData.cep} onChange={e => setChurchData({...churchData, cep: e.target.value})} onBlur={e => handleCepBlur(e.target.value)} className="w-full p-3 bg-slate-50 rounded-xl outline-none text-slate-800 border-none" /></div>
                  <div className="space-y-1 col-span-2"><label className="text-xs font-bold text-slate-400 uppercase ml-1">Cidade / Estado</label><input readOnly value={churchData.city ? `${churchData.city} - ${churchData.state}` : ''} className="w-full p-3 bg-slate-100 rounded-xl outline-none text-slate-500 border-none" /></div>
                </div>
                <div className="space-y-1"><label className="text-xs font-bold text-slate-400 uppercase ml-1">Endereço</label><input value={churchData.address} onChange={e => setChurchData({...churchData, address: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl outline-none text-slate-800 border-none" /></div>
                <button className="w-full py-4 bg-indigo-600 text-white font-bold rounded-2xl shadow-lg hover:bg-indigo-700 transition-all"><Save className="w-4 h-4 inline mr-2" /> Salvar Igreja</button>
              </div>
            </div>
          )}

          {activeTab === 'contacts' && (
            <div className="h-full flex flex-col overflow-hidden">
               <div className="flex justify-between items-center p-6 border-b border-slate-100 bg-white z-10"><div><h2 className="text-2xl font-bold text-slate-800">Contatos Koinonia</h2><p className="text-xs text-slate-400 font-medium uppercase">Registro unificado de membros</p></div><div className="flex gap-2"><div className="bg-slate-100 p-1 rounded-xl flex gap-1"><button onClick={() => setViewMode('list')} className={`p-1.5 rounded-lg transition-all ${viewMode === 'list' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}><List className="w-5 h-5" /></button><button onClick={() => setViewMode('blocks')} className={`p-1.5 rounded-lg transition-all ${viewMode === 'blocks' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'}`}><LayoutGrid className="w-5 h-5" /></button></div><button onClick={() => setIsImportModalOpen(true)} className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-200 text-slate-600 rounded-xl font-bold hover:bg-slate-50"><Upload className="w-4 h-4" /> Importar CSV</button><button className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-xl font-bold hover:bg-indigo-700 shadow-lg" onClick={() => { setEditingMember({ stage: MemberStage.VISITOR, interests: [], channel: 'MANUAL' }); setIsMemberModalOpen(true); }}><Plus className="w-4 h-4" /> Novo Contato</button></div></div>
               <div className="flex-1 overflow-hidden">{viewMode === 'list' ? renderMemberListView() : renderMemberGrid()}</div>
            </div>
          )}

          {activeTab === 'settings' && (
            <div className="p-8 h-full overflow-y-auto space-y-8 max-w-4xl mx-auto">
              <h2 className="text-3xl font-bold text-slate-800">Configurações & Perfil</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <section className="bg-white p-8 rounded-[40px] border border-slate-100 shadow-sm space-y-6">
                  <h3 className="font-bold text-slate-800 flex items-center gap-2"><User className="w-5 h-5 text-indigo-500" /> Meu Perfil</h3>
                  <form onSubmit={updateCurrentUser} className="space-y-4">
                    <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">Nome</label><input value={currentUser?.name || ''} onChange={e => setCurrentUser(prev => prev ? {...prev, name: e.target.value} : null)} className="w-full p-3 bg-slate-50 rounded-xl outline-none font-bold text-slate-700 border-none" /></div>
                    <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">WhatsApp</label><input value={currentUser?.whatsapp || ''} onChange={e => setCurrentUser(prev => prev ? {...prev, whatsapp: e.target.value} : null)} className="w-full p-3 bg-slate-50 rounded-xl outline-none text-slate-700 border-none" /></div>
                    <button type="submit" className="w-full py-3 bg-indigo-600 text-white font-bold rounded-xl shadow-lg">Salvar Perfil</button>
                  </form>
                </section>
                <section className="bg-white p-8 rounded-[40px] border border-slate-100 shadow-sm space-y-6">
                  <h3 className="font-bold text-slate-800 flex items-center gap-2"><Globe className="w-5 h-5 text-blue-500" /> Sistema</h3>
                  <div className="space-y-4">
                    <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">Fuso Horário</label><select value={timezone} onChange={e => setTimezone(e.target.value)} className="w-full p-3 bg-slate-50 rounded-xl outline-none text-sm font-bold text-slate-700 border-none">{TIMEZONES.map(t => <option key={t} value={t}>{t}</option>)}</select></div>
                    <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">Aparência</label><div className="flex gap-2"><button onClick={() => setTheme('light')} className={`flex-1 p-3 rounded-xl border-2 transition-all ${theme === 'light' ? 'bg-indigo-50 border-indigo-600 text-indigo-700' : 'bg-white border-slate-100 text-slate-400'}`}>Claro</button><button onClick={() => setTheme('dark')} className={`flex-1 p-3 rounded-xl border-2 transition-all ${theme === 'dark' ? 'bg-slate-800 border-slate-700 text-white' : 'bg-white border-slate-100 text-slate-400'}`}>Escuro</button></div></div>
                  </div>
                </section>
                <section className="bg-white p-8 rounded-[40px] border border-slate-100 shadow-sm col-span-1 md:col-span-2 flex items-center justify-between">
                  <div><h3 className="font-bold text-slate-800">Notificações Push</h3><p className="text-xs text-slate-400">Receber alertas de novos contatos e check-ins</p></div>
                  <button onClick={() => setPushEnabled(!pushEnabled)} className={`w-12 h-6 rounded-full relative transition-colors ${pushEnabled ? 'bg-indigo-600' : 'bg-slate-300'}`}><div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${pushEnabled ? 'right-1' : 'left-1'}`} /></button>
                </section>
              </div>
            </div>
          )}
        </div>
      </main>

      {/* Member Modal */}
      {isMemberModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[100] flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-white rounded-[40px] w-full max-w-3xl shadow-2xl overflow-hidden my-auto animate-in zoom-in duration-300">
            <div className="p-8 border-b border-slate-100 bg-indigo-600 text-white flex justify-between items-center"><div><h3 className="text-2xl font-bold">{editingMember?.id ? 'Editar Contato' : 'Novo Contato'}</h3></div><button onClick={() => setIsMemberModalOpen(false)} className="p-2 hover:bg-white/20 rounded-xl"><X className="w-6 h-6" /></button></div>
            <form onSubmit={handleSaveMember} className="p-8 space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">Nome</label><input required value={editingMember?.name || ''} onChange={e => setEditingMember({...editingMember, name: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl font-bold text-slate-800 border-none" /></div>
                <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">WhatsApp</label><input required value={editingMember?.phone || ''} onChange={e => setEditingMember({...editingMember, phone: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl text-slate-800 border-none" /></div>
                <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">Sexo</label><select value={editingMember?.gender || ''} onChange={e => setEditingMember({...editingMember, gender: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl font-bold text-slate-700 border-none"><option value="">Selecione</option><option value="Masculino">Masculino</option><option value="Feminino">Feminino</option></select></div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">Religião</label><input value={editingMember?.religion || ''} onChange={e => setEditingMember({...editingMember, religion: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl text-slate-800 border-none" /></div>
                <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">Origem (Canal)</label><input value={editingMember?.channel || ''} onChange={e => setEditingMember({...editingMember, channel: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl font-bold text-slate-800 border-none" /></div>
              </div>
              <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase">Endereço Completo</label><input value={editingMember?.address || ''} onChange={e => setEditingMember({...editingMember, address: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl text-slate-800 border-none" /></div>
              <button type="submit" className="w-full py-4 bg-indigo-600 text-white font-black rounded-xl shadow-lg mt-4 active:scale-95">Salvar Registro</button>
            </form>
          </div>
        </div>
      )}

      {/* Team Modal */}
      {isTeamModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[40px] w-full max-w-lg shadow-2xl overflow-hidden animate-in slide-in-from-bottom duration-300">
            <div className="p-8 border-b border-slate-100 bg-indigo-600 text-white flex justify-between items-center"><h3 className="text-xl font-bold">Gerir Líder</h3><button onClick={() => setIsTeamModalOpen(false)} className="p-2 hover:bg-white/20 rounded-xl"><X className="w-5 h-5" /></button></div>
            <form onSubmit={handleSaveTeamMember} className="p-8 space-y-4">
              <input required placeholder="Nome" value={editingTeamMember?.name || ''} onChange={e => setEditingTeamMember({...editingTeamMember, name: e.target.value})} className="w-full p-3 bg-slate-100 rounded-xl font-bold text-slate-800 border-none" />
              <div className="grid grid-cols-2 gap-4">
                <input type="email" placeholder="Email" value={editingTeamMember?.email || ''} onChange={e => setEditingTeamMember({...editingTeamMember, email: e.target.value})} className="w-full p-3 bg-slate-100 rounded-xl text-slate-700 border-none" />
                <input placeholder="WhatsApp" value={editingTeamMember?.whatsapp || ''} onChange={e => setEditingTeamMember({...editingTeamMember, whatsapp: e.target.value})} className="w-full p-3 bg-slate-100 rounded-xl font-bold text-indigo-600 border-none" />
              </div>
              <div className="space-y-3 pt-4 border-t border-slate-50"><label className="text-[10px] font-black text-slate-400 uppercase flex items-center gap-2"><Lock className="w-3 h-3" /> Permissões</label><div className="grid grid-cols-2 gap-2">{AVAILABLE_PERMISSIONS.map(p => ( <label key={p.id} className="flex items-center gap-2 p-2 bg-slate-50 rounded-lg cursor-pointer hover:bg-slate-100"> <input type="checkbox" checked={editingTeamMember?.permissions?.includes(p.id)} onChange={e => { const current = editingTeamMember?.permissions || []; const next = e.target.checked ? [...current, p.id] : current.filter(id => id !== p.id); setEditingTeamMember({...editingTeamMember, permissions: next}); }} className="rounded text-indigo-600" /> <span className="text-[10px] font-bold text-slate-600 uppercase">{p.label}</span> </label> ))}</div></div>
              <button type="submit" className="w-full py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl mt-6">Salvar Alterações Equipe</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Columns, 
  Zap, 
  Settings, 
  Bell, 
  Search, 
  User,
  LogOut,
  ChevronRight,
  Menu,
  X,
  Save,
  Trash2,
  Users as UsersIcon,
  Church as ChurchIcon,
  Contact as ContactIcon,
  CheckCircle,
  Plus,
  ArrowRight,
  Key,
  Globe,
  Palette,
  Clock,
  HelpCircle,
  ShieldCheck,
  Smartphone,
  List,
  LayoutGrid,
  MapPin,
  Upload,
  UserPlus,
  Edit2,
  Lock
} from 'lucide-react';
import KanbanBoard from './components/KanbanBoard';
import AnalyticsDashboard from './components/AnalyticsDashboard';
import AutomationSettings from './components/AutomationSettings';
import { INITIAL_MEMBERS, INTEGRATIONS, STAGES } from './constants';
import { Member, MemberStage, SystemUser, UserRole } from './types';

const TIMEZONES = [
  "(GMT-03:00) Brasília / São Paulo",
  "(GMT-04:00) Manaus / Campo Grande",
  "(GMT-05:00) Rio Branco",
  "(GMT-00:00) London / Lisbon",
  "(GMT+01:00) Paris / Berlin",
  "(GMT-05:00) New York / Miami"
];

const AVAILABLE_PERMISSIONS = [
  { id: 'view_dashboard', label: 'Ver Dashboard' },
  { id: 'manage_pipeline', label: 'Gerir Pipeline' },
  { id: 'manage_contacts', label: 'Gerir Contatos' },
  { id: 'manage_team', label: 'Gerir Equipe' },
  { id: 'manage_church', label: 'Configurar Igreja' },
  { id: 'manage_settings', label: 'Acesso às Configurações' }
];

const App: React.FC = () => {
  // Global App State
  const [theme, setTheme] = useState<'light' | 'dark'>('light');
  const [viewMode, setViewMode] = useState<'blocks' | 'list'>('list');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [activeTab, setActiveTab] = useState<'kanban' | 'analytics' | 'automation' | 'team' | 'church' | 'contacts' | 'settings'>('kanban');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isProfileOpen, setIsProfileOpen] = useState(false);

  // Auth & Data State
  const [currentUser, setCurrentUser] = useState<SystemUser | null>(null);
  const [teamMembers, setTeamMembers] = useState<SystemUser[]>([]);
  const [members, setMembers] = useState<Member[]>(INITIAL_MEMBERS);

  // Church & Settings State
  const [churchData, setChurchData] = useState({ 
    logo: '', 
    name: '', 
    cep: '', 
    address: '', 
    city: '', 
    state: '', 
    pastor: '' 
  });
  const [timezone, setTimezone] = useState(TIMEZONES[0]);
  const [pushEnabled, setPushEnabled] = useState(true);

  // Modal States
  const [isMemberModalOpen, setIsMemberModalOpen] = useState(false);
  const [editingMember, setEditingMember] = useState<Partial<Member> | null>(null);
  const [isTeamModalOpen, setIsTeamModalOpen] = useState(false);
  const [editingTeamMember, setEditingTeamMember] = useState<Partial<SystemUser> | null>(null);
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);

  const [loginForm, setLoginForm] = useState({ name: '', email: '', whatsapp: '', church: '', password: '' });

  // Core Actions
  const moveMember = (id: string, nextStage: MemberStage) => {
    setMembers(prev => prev.map(m => m.id === id ? { ...m, stage: nextStage } : m));
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const newUser: SystemUser = {
      id: Math.random().toString(36).substr(2, 9),
      name: loginForm.name || 'Usuário Koinonia',
      email: loginForm.email || 'usuario@koinonia.com',
      whatsapp: loginForm.whatsapp,
      role: UserRole.ADMIN,
      church: loginForm.church || 'Igreja Central',
      permissions: AVAILABLE_PERMISSIONS.map(p => p.id),
      avatar: 'https://picsum.photos/id/64/100/100'
    };
    setCurrentUser(newUser);
    setTeamMembers([newUser]); 
    setChurchData(prev => ({ ...prev, name: newUser.church, pastor: newUser.name }));
    setIsLoggedIn(true);
  };

  const handleCepBlur = async (cep: string) => {
    const cleanCep = cep.replace(/\D/g, '');
    if (cleanCep.length === 8) {
      try {
        const response = await fetch(`https://viacep.com.br/ws/${cleanCep}/json/`);
        const data = await response.json();
        if (!data.erro) {
          setChurchData(prev => ({
            ...prev,
            address: `${data.logradouro}, ${data.bairro}`,
            city: data.localidade,
            state: data.uf
          }));
        }
      } catch (error) { console.error("Erro CEP:", error); }
    }
  };

  const handleSaveMember = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingMember?.name) return;
    if (editingMember.id) {
      setMembers(prev => prev.map(m => m.id === editingMember.id ? (editingMember as Member) : m));
    } else {
      const newMember: Member = {
        ...(editingMember as Member),
        id: Math.random().toString(36).substr(2, 9),
        lastActivity: new Date(),
        registrationDate: new Date(),
        engagementScore: 10
      };
      setMembers(prev => [...prev, newMember]);
    }
    setIsMemberModalOpen(false);
  };

  const handleSaveTeamMember = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingTeamMember?.name) return;
    if (editingTeamMember.id) {
      setTeamMembers(prev => prev.map(u => u.id === editingTeamMember.id ? (editingTeamMember as SystemUser) : u));
    } else {
      const newUser: SystemUser = {
        ...(editingTeamMember as SystemUser),
        id: Math.random().toString(36).substr(2, 9),
        church: churchData.name,
        permissions: editingTeamMember.permissions || []
      };
      setTeamMembers(prev => [...prev, newUser]);
    }
    setIsTeamModalOpen(false);
  };

  const handleDeleteTeamMember = (id: string) => {
    if (id === currentUser?.id) return alert("Não é possível remover seu próprio usuário.");
    if (confirm("Remover este líder da equipe?")) {
      setTeamMembers(prev => prev.filter(u => u.id !== id));
    }
  };

  // Add missing updateCurrentUser function to fix error in settings tab
  const updateCurrentUser = (e: React.FormEvent) => {
    e.preventDefault();
    alert("Perfil atualizado com sucesso!");
    setIsProfileOpen(false);
  };

  const renderMemberGrid = () => (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 p-6 overflow-y-auto h-full">
      {members.map(m => (
        <div key={m.id} onClick={() => { setEditingMember(m); setIsMemberModalOpen(true); }} className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm hover:shadow-md transition-all cursor-pointer group">
          <div className="flex justify-between mb-3">
            <div className="w-10 h-10 rounded-2xl bg-indigo-50 flex items-center justify-center text-indigo-600 font-bold">{m.name[0]}</div>
            <span className="text-[9px] font-bold uppercase bg-slate-100 px-2 py-1 rounded-lg text-slate-500">{m.religion || 'Religião'}</span>
          </div>
          <h4 className="font-bold text-slate-800 truncate">{m.name}</h4>
          <p className="text-xs text-slate-400 truncate mb-1">{m.phone}</p>
          <p className="text-[10px] text-slate-400 truncate mb-4">{m.address || 'Endereço não informado'}</p>
          <div className="flex justify-between items-center pt-4 border-t border-slate-50">
            <span className="text-[10px] font-bold text-slate-500 uppercase">{m.gender || 'Sexo'}</span>
            <div className="flex gap-1">
              <button className="p-1.5 text-slate-300 hover:text-indigo-600"><Edit2 className="w-3.5 h-3.5" /></button>
