export default App;

export enum MemberStage {
  VISITOR = 'VISITOR',
  NEW_MEMBER = 'NEW_MEMBER',
  ACTIVE_MEMBER = 'ACTIVE_MEMBER',
  LEADER_IN_TRAINING = 'LEADER_IN_TRAINING',
  LEADER = 'LEADER'
}

export enum UserRole {
  ADMIN = 'ADMIN',
  PASTOR = 'PASTOR',
  LEADER = 'LEADER',
  VOLUNTEER = 'VOLUNTEER'
}

export enum EventType {
  SERVICE = 'SERVICE',
  MEETING = 'MEETING',
  EVENT = 'EVENT',
  FOLLOW_UP = 'FOLLOW_UP'
}

