  avatar?: string;
  permissions: string[];
  created_at?: Date;
}

export interface Member {
  id: string; // UUID
  name: string;
  email: string;
  phone: string;
  gender?: string;
  religion?: string;
  address?: string;
  stage: MemberStage;
  last_activity: Date;
  engagement_score: number; 
  church_id: string;
