}

const MemberCard: React.FC<MemberCardProps> = ({ member, onMove, onClick }) => {
  const [isGenerating, setIsGenerating] = useState(false);

  const getScoreColor = (score: number) => {
    if (score > 80) return 'text-green-600';
    if (score > 50) return 'text-amber-600';
    return 'text-red-600';
  };

  const handleNextStage = (e: React.MouseEvent) => {
    e.stopPropagation();
    const currentIndex = STAGES.findIndex(s => s.id === member.stage);
    if (currentIndex < STAGES.length - 1 && onMove) {
      onMove(member.id, STAGES[currentIndex + 1].id as MemberStage);
    }
  };

  const handleGenerateMessage = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (isGenerating) return;
    setIsGenerating(true);
    const stageLabel = STAGES.find(s => s.id === member.stage)?.label || member.stage;
    try {
      const msg = await generateHumanizedMessage(
        member.name, 
        stageLabel, 
        "Contato caloroso de acompanhamento da liderança"
      );
      alert(`Mensagem Gerada para ${member.name}:\n\n${msg}`);
    } catch (err) {
      console.error(err);
    } finally {
      setIsGenerating(false);
    }
  };

  const isAtLastStage = STAGES.findIndex(s => s.id === member.stage) === STAGES.length - 1;

  return (
    <div 
      onClick={() => onClick?.(member)}
      className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 hover:shadow-md transition-all group cursor-pointer active:scale-[0.98]"
    >
      <div className="flex justify-between items-start mb-2">
        <div className="flex flex-col overflow-hidden pr-2">
          <h4 className="font-bold text-slate-800 text-sm truncate">{member.name}</h4>
          <span className="text-[10px] font-bold text-indigo-500 uppercase tracking-tighter">{member.religion || 'Religião não inf.'}</span>
        </div>
        <button className="text-slate-400 hover:text-slate-600 shrink-0" onClick={(e) => e.stopPropagation()}>
          <MoreVertical className="w-4 h-4" />
        </button>
      </div>

      <div className="space-y-1 mb-3">
        <div className="flex items-center gap-1.5 text-[10px] text-slate-400 font-medium">
          <Mail className="w-3 h-3 text-slate-300" />
          <span className="truncate">{member.email || 'Email não informado'}</span>
        </div>
        <div className="flex items-start gap-1.5 text-[10px] text-slate-400 font-medium">
          <MapPin className="w-3 h-3 text-slate-300 shrink-0 mt-0.5" />
          <span className="line-clamp-1">{member.address || 'Sem endereço'}</span>
        </div>
      </div>

      <div className="flex items-center gap-3 mb-3 text-[10px] text-slate-500 font-bold uppercase">
        <div className="flex items-center gap-1">
          <Calendar className="w-3 h-3" />
          {new Date(member.last_activity).toLocaleDateString('pt-BR')}
        </div>
        <div className={getScoreColor(member.engagement_score)}>
          {member.engagement_score}% Engajado
        </div>
      </div>

      <div className="flex items-center justify-between pt-3 border-t border-slate-100">
        <div className="flex -space-x-2">
          {member.channel === 'INSTAGRAM' && (
            <div className="w-6 h-6 rounded-full bg-pink-100 flex items-center justify-center text-pink-600 border-2 border-white" title="Instagram">
              <span className="text-[10px] font-black">IG</span>
            </div>
          )}
          {member.channel === 'QR_CODE' && (
            <div className="w-6 h-6 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 border-2 border-white" title="QR Code">
              <span className="text-[10px] font-black">QR</span>
            </div>
          )}
          {member.channel === 'MANUAL' && (
            <div className="w-6 h-6 rounded-full bg-slate-100 flex items-center justify-center text-slate-600 border-2 border-white" title="Manual">
              <span className="text-[10px] font-black">M</span>
            </div>
          )}
          {!['INSTAGRAM', 'QR_CODE', 'MANUAL'].includes(member.channel) && (
             <div className="w-6 h-6 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600 border-2 border-white" title={member.channel}>
              <span className="text-[10px] font-black">{member.channel?.[0]?.toUpperCase()}</span>
            </div>
          )}
        </div>

        <div className="flex gap-2">
          <button 
            onClick={handleGenerateMessage}
            disabled={isGenerating}
            className="p-1.5 rounded-lg bg-emerald-50 text-emerald-600 hover:bg-emerald-100 disabled:opacity-50 transition-colors"
            title="Gerar Mensagem IA"
          >
            {isGenerating ? <Loader2 className="w-4 h-4 animate-spin" /> : <MessageCircle className="w-4 h-4" />}
          </button>
          <button 
            onClick={handleNextStage}
            disabled={isAtLastStage}
            className={`p-1.5 rounded-lg bg-slate-50 text-slate-600 hover:bg-slate-100 disabled:opacity-30 transition-colors`}
            title={isAtLastStage ? "Estágio Final" : "Próximo Estágio"}
          >
            <ArrowRight className="w-4 h-4" />
          </button>
        </div>
      </div>
    </div>
  );
};

export default MemberCard;

