          <div className="w-full md:w-[45%] bg-indigo-600 p-10 flex flex-col justify-between text-white relative">
            <div className="absolute top-0 left-0 w-full h-full overflow-hidden opacity-10">
               <div className="absolute top-10 left-10 w-40 h-40 border-8 border-white rounded-full"></div>
               <div className="absolute bottom-10 right-10 w-20 h-20 bg-white rounded-3xl rotate-45"></div>
            </div>
            <div className="relative z-10">
              <div className="w-14 h-14 bg-white/20 backdrop-blur-md rounded-2xl flex items-center justify-center mb-6 border border-white/30">
                <span className="font-black text-2xl">K</span>
              </div>
              <h1 className="text-4xl font-black leading-tight tracking-tighter">Koinonia<br/>Growth</h1>
            </div>
            <div className="relative z-10">
              <p className="text-indigo-100 text-sm font-medium leading-relaxed">
                {loginMode === 'login' 
