          <tbody className="divide-y divide-slate-100">
            {members.map(member => (
              <tr key={member.id} className="hover:bg-slate-50 transition-colors group cursor-pointer" onClick={() => { setEditingMember(member); setIsMemberModalOpen(true); }}>
