                <div className="relative"><Tag className="absolute left-3 top-3 w-4 h-4 text-slate-300" /><input placeholder="Ex: Música, Jovens, Casais..." value={editingMember?.interests?.join(', ') || ''} onChange={e => setEditingMember({...editingMember, interests: e.target.value.split(',').map(s => s.trim())})} className="w-full pl-10 pr-3 py-3 bg-slate-50 rounded-xl text-slate-800 border-none outline-none focus:ring-2 focus:ring-indigo-100" /></div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Endereço Completo</label>
                <div className="relative"><MapPin className="absolute left-3 top-3 w-4 h-4 text-slate-300" /><input value={editingMember?.address || ''} onChange={e => setEditingMember({...editingMember, address: e.target.value})} className="w-full pl-10 pr-3 py-3 bg-slate-50 rounded-xl text-slate-800 border-none outline-none focus:ring-2 focus:ring-indigo-100" /></div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Pessoa Responsável</label>
                <div className="relative">
                  <Shield className="absolute left-3 top-3.5 w-4 h-4 text-slate-300 z-10" />
                  <select 
                    value={editingMember?.responsible_leader_id || currentUser?.id || ''} 
                    onChange={e => setEditingMember({...editingMember, responsible_leader_id: e.target.value})}
                    className="w-full pl-10 pr-10 py-3.5 bg-slate-50 rounded-xl font-bold text-slate-800 border-none outline-none focus:ring-2 focus:ring-indigo-100 appearance-none cursor-pointer"
                  >
                    {teamMembers.map(leader => (
                      <option key={leader.id} value={leader.id}>
                        {leader.name} {leader.id === currentUser?.id ? '(Você)' : ''}
                      </option>
                    ))}
                    {!teamMembers.find(t => t.id === currentUser?.id) && currentUser && (
                       <option value={currentUser.id}>{currentUser.name} (Você)</option>
                    )}
                  </select>
                  <ChevronRight className="absolute right-4 top-3.5 w-4 h-4 text-slate-300 rotate-90 pointer-events-none" />
                </div>
              </div>

              <button type="submit" className="w-full py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 active:scale-95 transition-all mt-4">
                Salvar Registro Completo
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Team Modal */}
      {isTeamModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[40px] w-full max-w-lg shadow-2xl overflow-hidden animate-in slide-in-from-bottom duration-300">
            <div className="p-8 border-b border-slate-100 bg-indigo-600 text-white flex justify-between items-center"><h3 className="text-xl font-bold">Gerir Membro da Equipe</h3><button onClick={() => setIsTeamModalOpen(false)} className="p-2 hover:bg-white/20 rounded-xl"><X className="w-5 h-5" /></button></div>
            <form onSubmit={handleSaveTeamMember} className="p-8 space-y-4">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Nome</label>
                <input required placeholder="Nome do líder/voluntário" value={editingTeamMember?.name || ''} onChange={e => setEditingTeamMember({...editingTeamMember, name: e.target.value})} className="w-full p-3 bg-slate-100 rounded-xl font-bold text-slate-800 border-none focus:ring-2 focus:ring-indigo-100 outline-none" />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Email</label>
                  <input type="email" placeholder="email@igreja.com" value={editingTeamMember?.email || ''} onChange={e => setEditingTeamMember({...editingTeamMember, email: e.target.value})} className="w-full p-3 bg-slate-100 rounded-xl text-slate-700 border-none focus:ring-2 focus:ring-indigo-100 outline-none" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-1">WhatsApp</label>
                  <input placeholder="(00) 00000-0000" value={editingTeamMember?.whatsapp || ''} onChange={e => setEditingTeamMember({...editingTeamMember, whatsapp: e.target.value})} className="w-full p-3 bg-slate-100 rounded-xl font-bold text-indigo-600 border-none focus:ring-2 focus:ring-indigo-100 outline-none" />
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Função na Equipe</label>
                <div className="relative">
                  <Briefcase className="absolute left-3 top-3.5 w-4 h-4 text-slate-300 z-10" />
                  <select 
                    value={editingTeamMember?.role || UserRole.LEADER} 
                    onChange={e => setEditingTeamMember({...editingTeamMember, role: e.target.value as UserRole})}
                    className="w-full pl-10 pr-10 py-3.5 bg-slate-100 rounded-xl font-bold text-slate-800 border-none outline-none focus:ring-2 focus:ring-indigo-100 appearance-none cursor-pointer"
                  >
                    <option value={UserRole.PASTOR}>Pastor</option>
                    <option value={UserRole.LEADER}>Líder</option>
                    <option value={UserRole.RECEPTION}>Recepção</option>
                    <option value={UserRole.VOLUNTEER}>Voluntário</option>
                    <option value={UserRole.ADMIN}>Administrador</option>
                  </select>
                  <ChevronRight className="absolute right-4 top-3.5 w-4 h-4 text-slate-300 rotate-90 pointer-events-none" />
                </div>
              </div>

              <div className="space-y-3 pt-4 border-t border-slate-50">
                <label className="text-[10px] font-black text-slate-400 uppercase flex items-center gap-2"><Lock className="w-3 h-3" /> Permissões de Acesso</label>
                <div className="grid grid-cols-2 gap-2">
                  {AVAILABLE_PERMISSIONS.map(p => (
                    <label key={p.id} className="flex items-center gap-2 p-2 bg-slate-50 rounded-lg cursor-pointer hover:bg-slate-100 transition-colors">
                      <input 
                        type="checkbox" 
                        checked={editingTeamMember?.permissions?.includes(p.id)} 
                        onChange={e => {
                          const current = editingTeamMember?.permissions || [];
                          const next = e.target.checked ? [...current, p.id] : current.filter(id => id !== p.id);
                          setEditingTeamMember({...editingTeamMember, permissions: next});
                        }} 
                        className="rounded text-indigo-600 focus:ring-indigo-500" 
                      />
                      <span className="text-[10px] font-bold text-slate-600 uppercase">{p.label}</span>
                    </label>
                  ))}
                </div>
              </div>

              <button type="submit" className="w-full py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 active:scale-95 transition-all mt-6">
                Salvar Alterações Equipe
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

export enum MemberStage {
  VISITOR = 'VISITOR',
  NEW_MEMBER = 'NEW_MEMBER',
  ACTIVE_MEMBER = 'ACTIVE_MEMBER',
  LEADER_IN_TRAINING = 'LEADER_IN_TRAINING',
  LEADER = 'LEADER'
}

export enum UserRole {
  ADMIN = 'ADMIN',
  PASTOR = 'PASTOR',
  LEADER = 'LEADER',
  RECEPTION = 'RECEPTION',
  VOLUNTEER = 'VOLUNTEER'
}

export enum EventType {
  SERVICE = 'SERVICE',
  MEETING = 'MEETING',
  EVENT = 'EVENT',
  FOLLOW_UP = 'FOLLOW_UP'
}

export interface ScheduleEvent {
  id: string;
  title: string;
  description?: string;
  start_date: Date;
  end_date: Date;
  location?: string;
  type: EventType;
  church_id: string;
  created_at: Date;
}

export interface SystemUser {
  id: string; // UUID em ambiente persistente
  name: string;
  email: string;
  whatsapp?: string;
  role: UserRole;
  church_id: string; // Relacionamento com a tabela de igrejas
  avatar?: string;
  permissions: string[];
  created_at?: Date;
}

export interface Member {
  id: string; // UUID
  name: string;
  email: string;
  phone: string;
  gender?: string;
  religion?: string;
  cep?: string; // Campo adicionado para busca automatizada
  address?: string;
  avatar?: string; // Campo adicionado para "Logo"/Foto do contato
  stage: MemberStage;
  last_activity: Date;
  engagement_score: number; 
  church_id: string;
  responsible_leader_id?: string; // FK para SystemUser
  registration_date: Date;
  channel: string;
  interests?: string[];
  created_at?: Date;
}

export interface Church {
  id: string;
  name: string;
  logo_url?: string;
  email?: string; // Campo adicionado
  cep?: string;
  address?: string;
  city?: string;
  state?: string;
  pastor_id?: string; // FK para SystemUser (Pastor Titular)
  settings?: Record<string, any>;
}

export interface AuditLog {
  id: string;
  user_id: string;
  action: string;
  table_name: string;
  record_id: string;
  details: any;
  created_at: Date;
}

import React, { useState, useEffect, useRef } from 'react';
import { 
  LayoutDashboard, 
  Columns, 
  Zap, 
  Settings, 
  Bell, 
  Search, 
  User,
  LogOut,
  ChevronRight,
  Menu,
  X,
  Save,
  Trash2,
  Users as UsersIcon,
  Church as ChurchIcon,
  Contact as ContactIcon,
  CheckCircle,
  Plus,
  ArrowRight,
  Key,
  Globe,
  Palette,
  Clock,
  HelpCircle,
  ShieldCheck,
  Smartphone,
  List,
  LayoutGrid,
  MapPin,
  Upload,
  UserPlus,
  Edit2,
  Lock,
  CalendarDays,
  Mail,
  Eye,
  EyeOff,
  Tag,
  Shield,
  Briefcase,
  Camera
} from 'lucide-react';
import KanbanBoard from './components/KanbanBoard';
import AnalyticsDashboard from './components/AnalyticsDashboard';
import AutomationSettings from './components/AutomationSettings';
import ScheduleModule from './components/ScheduleModule';
import { INITIAL_MEMBERS, INITIAL_EVENTS, INTEGRATIONS, STAGES } from './constants';
import { Member, MemberStage, SystemUser, UserRole, ScheduleEvent } from './types';
import { KoinoniaDB } from './services/db';

const TIMEZONES = [
  "(GMT-03:00) Brasília / São Paulo",
  "(GMT-04:00) Manaus / Campo Grande",
  "(GMT-05:00) Rio Branco",
  "(GMT-00:00) London / Lisbon",
  "(GMT+01:00) Paris / Berlin",
  "(GMT-05:00) New York / Miami"
];

const AVAILABLE_PERMISSIONS = [
  { id: 'view_dashboard', label: 'Ver Dashboard' },
  { id: 'manage_pipeline', label: 'Gerir Pipeline' },
  { id: 'manage_contacts', label: 'Gerir Contatos' },
  { id: 'manage_team', label: 'Gerir Equipe' },
  { id: 'manage_church', label: 'Configurar Igreja' },
  { id: 'manage_settings', label: 'Acesso às Configurações' }
];

const App: React.FC = () => {
  // Global App State
  const [theme, setTheme] = useState<'light' | 'dark'>('light');
  const [viewMode, setViewMode] = useState<'blocks' | 'list'>('list');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loginMode, setLoginMode] = useState<'login' | 'register'>('login');
  const [showPassword, setShowPassword] = useState(false);
  const [activeTab, setActiveTab] = useState<'kanban' | 'analytics' | 'automation' | 'team' | 'church' | 'contacts' | 'settings' | 'agenda'>('kanban');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isProfileOpen, setIsProfileOpen] = useState(false);

  // Auth & Data State
  const [currentUser, setCurrentUser] = useState<SystemUser | null>(null);
  const [teamMembers, setTeamMembers] = useState<SystemUser[]>([]);
  const [members, setMembers] = useState<Member[]>([]);
  const [events, setEvents] = useState<ScheduleEvent[]>([]);

  // Church & Settings State
  const [churchData, setChurchData] = useState({ 
    logo: '', 
    name: '', 
    email: '', 
    cep: '', 
    address: '', 
    city: '', 
    state: '', 
    pastor: '' 
  });
  const [timezone, setTimezone] = useState(TIMEZONES[0]);
  const [pushEnabled, setPushEnabled] = useState(true);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const memberFileInputRef = useRef<HTMLInputElement>(null);

  // Persistence Logic - Load Data
  useEffect(() => {
    const loadedMembers = KoinoniaDB.getAllMembers();
    const loadedEvents = KoinoniaDB.getAllEvents();
    const loadedTeam = KoinoniaDB.getTeamMembers();
    const loadedChurch = KoinoniaDB.getChurchData();

    setMembers(loadedMembers);
    setEvents(loadedEvents);
    setTeamMembers(loadedTeam);
    if (loadedChurch) setChurchData(loadedChurch);

    const savedUser = localStorage.getItem('koinonia_session');
    if (savedUser) {
      setCurrentUser(JSON.parse(savedUser));
      setIsLoggedIn(true);
    }
  }, []);

  // Persistence Logic - Save Data on Change
  useEffect(() => { if (members.length > 0) KoinoniaDB.saveMembers(members); }, [members]);
  useEffect(() => { if (events.length > 0) KoinoniaDB.saveEvents(events); }, [events]);
  useEffect(() => { if (teamMembers.length > 0) KoinoniaDB.saveTeamMembers(teamMembers); }, [teamMembers]);
  useEffect(() => { if (churchData.name) KoinoniaDB.saveChurchData(churchData); }, [churchData]);

  // Modal States
  const [isMemberModalOpen, setIsMemberModalOpen] = useState(false);
  const [editingMember, setEditingMember] = useState<Partial<Member> | null>(null);
  const [isTeamModalOpen, setIsTeamModalOpen] = useState(false);
  const [editingTeamMember, setEditingTeamMember] = useState<Partial<SystemUser> | null>(null);
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);

  const [loginForm, setLoginForm] = useState({ name: '', email: '', whatsapp: '', church: '', password: '' });

  // Core Actions
  const moveMember = (id: string, nextStage: MemberStage) => {
    setMembers(prev => prev.map(m => m.id === id ? { ...m, stage: nextStage } : m));
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const newUser: SystemUser = {
      id: Math.random().toString(36).substr(2, 9),
      name: loginForm.name || 'Usuário Koinonia',
      email: loginForm.email || 'usuario@koinonia.com',
      whatsapp: loginForm.whatsapp,
      role: UserRole.ADMIN,
      church_id: loginForm.church || 'Igreja Central',
      permissions: AVAILABLE_PERMISSIONS.map(p => p.id),
      avatar: 'https://picsum.photos/id/64/100/100'
    };

    setCurrentUser(newUser);
    if (!teamMembers.find(t => t.email === newUser.email)) {
        setTeamMembers(prev => [...prev, newUser]);
    }

    setChurchData(prev => ({ ...prev, name: newUser.church_id, pastor: newUser.name }));
    localStorage.setItem('koinonia_session', JSON.stringify(newUser));
    setIsLoggedIn(true);
  };

  const handleLogout = () => {
    localStorage.removeItem('koinonia_session');
    setIsLoggedIn(false);
    setCurrentUser(null);
  };

  const handleCepBlur = async (cep: string) => {
    const cleanCep = cep.replace(/\D/g, '');
    if (cleanCep.length === 8) {
      try {
        const response = await fetch(`https://viacep.com.br/ws/${cleanCep}/json/`);
        const data = await response.json();
        if (!data.erro) {
          setChurchData(prev => ({
            ...prev,
            address: `${data.logradouro}, ${data.bairro}`,
            city: data.localidade,
            state: data.uf
          }));
        }
      } catch (error) { console.error("Erro CEP:", error); }
    }
  };

  // Nova função para busca automatizada no módulo de Contatos
  const handleMemberCepBlur = async (cep: string) => {
    const cleanCep = cep.replace(/\D/g, '');
    if (cleanCep.length === 8) {
      try {
        const response = await fetch(`https://viacep.com.br/ws/${cleanCep}/json/`);
        const data = await response.json();
        if (!data.erro) {
          setEditingMember(prev => prev ? ({
            ...prev,
            address: `${data.logradouro}, ${data.bairro}, ${data.localidade} - ${data.uf}`
          }) : null);
        }
      } catch (error) { console.error("Erro CEP Contato:", error); }
    }
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setChurchData({ ...churchData, logo: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleMemberAvatarUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setEditingMember(prev => prev ? ({ ...prev, avatar: reader.result as string }) : null);
      };
      reader.readAsDataURL(file);
    }
  };

  const triggerFileUpload = () => {
    fileInputRef.current?.click();
  };

  const triggerMemberFileUpload = () => {
    memberFileInputRef.current?.click();
  };

  const handleSaveMember = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingMember?.name) return;

    if (editingMember.id) {
      setMembers(prev => prev.map(m => m.id === editingMember.id ? (editingMember as Member) : m));
    } else {
      const newMember: Member = {
        ...(editingMember as Member),
        id: Math.random().toString(36).substr(2, 9),
        last_activity: new Date(),
        registration_date: new Date(),
        engagement_score: 10,
        church_id: '1',
        channel: editingMember.channel || 'MANUAL',
        responsible_leader_id: editingMember.responsible_leader_id || currentUser?.id // Prioriza seleção manual do modal, senão automatiza pelo criador
      };
      setMembers(prev => [...prev, newMember]);
    }
    setIsMemberModalOpen(false);
  };

  const handleSaveTeamMember = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingTeamMember?.name) return;
    if (editingTeamMember.id) {
      setTeamMembers(prev => prev.map(u => u.id === editingTeamMember.id ? (editingTeamMember as SystemUser) : u));
    } else {
      const newUser: SystemUser = {
        ...(editingTeamMember as SystemUser),
        id: Math.random().toString(36).substr(2, 9),
        church_id: churchData.name,
        permissions: editingTeamMember.permissions || []
      };
      setTeamMembers(prev => [...prev, newUser]);
    }
    setIsTeamModalOpen(false);
  };

  const handleDeleteTeamMember = (id: string) => {
    if (id === currentUser?.id) return alert("Não é possível remover seu próprio usuário.");
    if (confirm("Remover este líder da equipe?")) {
      setTeamMembers(prev => prev.filter(u => u.id !== id));
    }
  };

  const updateCurrentUser = (e: React.FormEvent) => {
    e.preventDefault();
    alert("Perfil atualizado com sucesso!");
    setIsProfileOpen(false);
  };

  const getLeaderName = (id?: string) => {
    if (!id) return 'Não atribuído';
    return teamMembers.find(t => t.id === id)?.name || 'Líder Desconhecido';
  };

  const renderMemberGrid = () => (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 p-6 overflow-y-auto h-full">
      {members.map(m => (
        <div key={m.id} onClick={() => { setEditingMember(m); setIsMemberModalOpen(true); }} className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm hover:shadow-md transition-all cursor-pointer group flex flex-col justify-between">
          <div>
            <div className="flex justify-between mb-3">
              <div className="w-10 h-10 rounded-2xl bg-indigo-50 flex items-center justify-center text-indigo-600 font-bold overflow-hidden">
                {m.avatar ? <img src={m.avatar} className="w-full h-full object-cover" /> : m.name[0]}
              </div>
              <span className="text-[9px] font-bold uppercase bg-slate-100 px-2 py-1 rounded-lg text-slate-500">{m.religion || 'Religião'}</span>
            </div>
            <h4 className="font-bold text-slate-800 truncate">{m.name}</h4>
            <div className="flex flex-col gap-0.5 mt-1">
              <div className="flex items-center gap-1.5 text-xs text-slate-500">
                <Smartphone className="w-3 h-3 text-slate-300" />
                <span>{m.phone}</span>
              </div>
              <div className="flex items-center gap-1.5 text-xs text-slate-400">
                <Mail className="w-3 h-3 text-slate-300" />
                <span className="truncate">{m.email}</span>
              </div>
            </div>
            <p className="text-[10px] text-slate-400 mt-2 flex items-start gap-1">
              <MapPin className="w-3 h-3 shrink-0" />
              <span className="line-clamp-2">{m.address || 'Endereço não informado'}</span>
            </p>
            {m.interests && m.interests.length > 0 && (
              <div className="flex flex-wrap gap-1 mt-3">
                {m.interests.map((int, i) => (
                  <span key={i} className="px-2 py-0.5 bg-indigo-50 text-indigo-600 text-[9px] font-bold rounded-lg uppercase tracking-tight">{int}</span>
                ))}
              </div>
            )}
          </div>
          <div className="flex justify-between items-center pt-4 mt-4 border-t border-slate-50">
            <div className="flex flex-col">
              <span className="text-[9px] font-black text-slate-300 uppercase leading-none mb-1">Responsável</span>
              <span className="text-[10px] font-bold text-slate-500 truncate max-w-[100px]">{getLeaderName(m.responsible_leader_id)}</span>
            </div>
            <div className="flex gap-1">
              <button className="p-1.5 text-slate-300 hover:text-indigo-600" onClick={(e) => { e.stopPropagation(); setEditingMember(m); setIsMemberModalOpen(true); }}><Edit2 className="w-3.5 h-3.5" /></button>
              <button onClick={(e) => { e.stopPropagation(); setMembers(members.filter(mem => mem.id !== m.id)); }} className="p-1.5 text-slate-300 hover:text-red-600"><Trash2 className="w-3.5 h-3.5" /></button>
            </div>
          </div>
        </div>
      ))}
    </div>
  );

  const renderMemberListView = () => (
    <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden mx-6 mb-6 flex-1 flex flex-col">
      <div className="overflow-y-auto">
        <table className="w-full text-sm text-left">
          <thead className="bg-slate-50 text-slate-500 uppercase text-[10px] font-bold sticky top-0">
            <tr>
              <th className="px-6 py-4">Membro / Email</th>
              <th className="px-6 py-4">WhatsApp</th>
              <th className="px-6 py-4">Estágio / Interesses</th>
              <th className="px-6 py-4">Responsável</th>
              <th className="px-6 py-4 text-right">Ações</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {members.map(member => (
              <tr key={member.id} className="hover:bg-slate-50 transition-colors group cursor-pointer" onClick={() => { setEditingMember(member); setIsMemberModalOpen(true); }}>
                <td className="px-6 py-4">
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 rounded-lg bg-slate-100 flex items-center justify-center text-[10px] font-bold text-slate-500 uppercase overflow-hidden">
                      {member.avatar ? <img src={member.avatar} className="w-full h-full object-cover" /> : member.name[0]}
                    </div>
                    <div>
                      <p className="font-bold text-slate-800">{member.name}</p>
