  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loginMode, setLoginMode] = useState<'login' | 'register'>('login');
  const [showPassword, setShowPassword] = useState(false);
  const [activeTab, setActiveTab] = useState<'analytics' | 'kanban' | 'automation' | 'team' | 'church' | 'contacts' | 'settings' | 'agenda'>('analytics');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isProfileOpen, setIsProfileOpen] = useState(false);

  // Auth & Data State
  const [currentUser, setCurrentUser] = useState<SystemUser | null>(null);
  const [teamMembers, setTeamMembers] = useState<SystemUser[]>([]);
  const [members, setMembers] = useState<Member[]>([]);
  const [events, setEvents] = useState<ScheduleEvent[]>([]);

  // Church & Settings State
  const [churchData, setChurchData] = useState({ 
    logo: '', 
    name: '', 
    email: '', 
    cep: '', 
    address: '', 
    city: '', 
    state: '', 
    pastor: '' 
  });
  const [timezone, setTimezone] = useState(TIMEZONES[0]);
  const [language, setLanguage] = useState(LANGUAGES[0].id);
  const [pushEnabled, setPushEnabled] = useState(true);
  const [emailAlertsEnabled, setEmailAlertsEnabled] = useState(true);
  const [newPassword, setNewPassword] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const memberFileInputRef = useRef<HTMLInputElement>(null);
  const userAvatarInputRef = useRef<HTMLInputElement>(null);

  const APP_VERSION = "2.4.0-stable";

  // Persistence Logic - Load Data
  useEffect(() => {
    const loadedMembers = KoinoniaDB.getAllMembers();
    const loadedEvents = KoinoniaDB.getAllEvents();
    const loadedTeam = KoinoniaDB.getTeamMembers();
    const loadedChurch = KoinoniaDB.getChurchData();

    setMembers(loadedMembers);
    setEvents(loadedEvents);
    setTeamMembers(loadedTeam);
    if (loadedChurch) setChurchData(loadedChurch);

    const savedUser = localStorage.getItem('koinonia_session');
    if (savedUser) {
      setCurrentUser(JSON.parse(savedUser));
      setIsLoggedIn(true);
    }
  }, []);

  // Persistence Logic - Save Data on Change
  useEffect(() => { if (members.length > 0) KoinoniaDB.saveMembers(members); }, [members]);
  useEffect(() => { if (events.length > 0) KoinoniaDB.saveEvents(events); }, [events]);
  useEffect(() => { if (teamMembers.length > 0) KoinoniaDB.saveTeamMembers(teamMembers); }, [teamMembers]);
  useEffect(() => { if (churchData.name) KoinoniaDB.saveChurchData(churchData); }, [churchData]);

  // Modal States
  const [isMemberModalOpen, setIsMemberModalOpen] = useState(false);
  const [editingMember, setEditingMember] = useState<Partial<Member> | null>(null);
  const [isTeamModalOpen, setIsTeamModalOpen] = useState(false);
  const [editingTeamMember, setEditingTeamMember] = useState<Partial<SystemUser> | null>(null);
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);

  const [loginForm, setLoginForm] = useState({ name: '', email: '', whatsapp: '', church: '', password: '' });

  // Core Actions
  const moveMember = (id: string, nextStage: MemberStage) => {
    setMembers(prev => prev.map(m => m.id === id ? { ...m, stage: nextStage } : m));
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const newUser: SystemUser = {
      id: Math.random().toString(36).substr(2, 9),
      name: loginForm.name || 'Usuário Koinonia',
      email: loginForm.email || 'usuario@koinonia.com',
      whatsapp: loginForm.whatsapp,
      role: UserRole.ADMIN,
      church_id: loginForm.church || 'Igreja Central',
      permissions: AVAILABLE_PERMISSIONS.map(p => p.id),
      avatar: ''
    };

    setCurrentUser(newUser);
    if (!teamMembers.find(t => t.email === newUser.email)) {
        setTeamMembers(prev => [...prev, newUser]);
    }

    setChurchData(prev => ({ ...prev, name: newUser.church_id, pastor: newUser.name }));
    localStorage.setItem('koinonia_session', JSON.stringify(newUser));
    setIsLoggedIn(true);
  };

  const handleLogout = () => {
    localStorage.removeItem('koinonia_session');
    setIsLoggedIn(false);
    setCurrentUser(null);
  };

  const handleCepBlur = async (cep: string) => {
    const cleanCep = cep.replace(/\D/g, '');
    if (cleanCep.length === 8) {
      try {
        const response = await fetch(`https://viacep.com.br/ws/${cleanCep}/json/`);
        const data = await response.json();
        if (!data.erro) {
          setChurchData(prev => ({
            ...prev,
            address: `${data.logradouro}, ${data.bairro}`,
            city: data.localidade,
            state: data.uf
          }));
        }
      } catch (error) { console.error("Erro CEP:", error); }
    }
  };

  const handleMemberCepBlur = async (cep: string) => {
    const cleanCep = cep.replace(/\D/g, '');
    if (cleanCep.length === 8) {
      try {
        const response = await fetch(`https://viacep.com.br/ws/${cleanCep}/json/`);
        const data = await response.json();
        if (!data.erro) {
          setEditingMember(prev => prev ? ({
            ...prev,
            address: `${data.logradouro}, ${data.bairro}, ${data.localidade} - ${data.uf}`
          }) : null);
        }
      } catch (error) { console.error("Erro CEP Contato:", error); }
    }
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setChurchData({ ...churchData, logo: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleMemberAvatarUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setEditingMember(prev => prev ? ({ ...prev, avatar: reader.result as string }) : null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleUserAvatarUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setCurrentUser(prev => prev ? ({ ...prev, avatar: reader.result as string }) : null);
      };
      reader.readAsDataURL(file);
    }
  };

  const triggerFileUpload = () => {
    fileInputRef.current?.click();
  };

  const triggerMemberFileUpload = () => {
    memberFileInputRef.current?.click();
  };

  const triggerUserAvatarUpload = () => {
    userAvatarInputRef.current?.click();
  };

  const downloadUserAvatar = () => {
    if (!currentUser?.avatar) return;
    const link = document.createElement('a');
    link.href = currentUser.avatar;
    link.download = `koinonia-perfil-${currentUser.name.toLowerCase().replace(/\s+/g, '-')}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleSaveMember = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingMember?.name) return;

    if (editingMember.id) {
      setMembers(prev => prev.map(m => m.id === editingMember.id ? (editingMember as Member) : m));
    } else {
      const newMember: Member = {
        ...(editingMember as Member),
        id: Math.random().toString(36).substr(2, 9),
        last_activity: new Date(),
        registration_date: new Date(),
        engagement_score: 10,
        church_id: '1',
        channel: editingMember.channel || 'MANUAL',
        responsible_leader_id: editingMember.responsible_leader_id || currentUser?.id
      };
      setMembers(prev => [...prev, newMember]);
    }
    setIsMemberModalOpen(false);
  };

  const handleSaveTeamMember = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingTeamMember?.name) return;
    if (editingTeamMember.id) {
      setTeamMembers(prev => prev.map(u => u.id === editingTeamMember.id ? (editingTeamMember as SystemUser) : u));
    } else {
      const newUser: SystemUser = {
        ...(editingTeamMember as SystemUser),
        id: Math.random().toString(36).substr(2, 9),
        church_id: churchData.name,
        permissions: editingTeamMember.permissions || []
      };
      setTeamMembers(prev => [...prev, newUser]);
    }
    setIsTeamModalOpen(false);
  };

  const handleDeleteTeamMember = (id: string) => {
    if (id === currentUser?.id) return alert("Não é possível remover seu próprio usuário.");
    if (confirm("Remover este líder da equipe?")) {
      setTeamMembers(prev => prev.filter(u => u.id !== id));
    }
  };

  const updateCurrentUser = (e: React.FormEvent) => {
    e.preventDefault();
    if (currentUser) {
      // Persistir alteração de perfil e whatsapp no localStorage
      localStorage.setItem('koinonia_session', JSON.stringify(currentUser));
      // Sincronizar na lista da equipe para consistência visual
      setTeamMembers(prev => prev.map(t => t.id === currentUser.id ? currentUser : t));
    }

    if (newPassword) {
      alert("Perfil e senha atualizados com sucesso!");
      setNewPassword('');
    } else {
      alert("Perfil atualizado com sucesso!");
    }
    setIsProfileOpen(false);
  };

  const getLeaderName = (id?: string) => {
    if (!id) return 'Não atribuído';
    return teamMembers.find(t => t.id === id)?.name || 'Líder Desconhecido';
  };

  const renderMemberGrid = () => (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 p-6 overflow-y-auto h-full">
      {members.map(m => (
        <div key={m.id} onClick={() => { setEditingMember(m); setIsMemberModalOpen(true); }} className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm hover:shadow-md transition-all cursor-pointer group flex flex-col justify-between">
          <div>
            <div className="flex justify-between mb-3">
              <div className="w-10 h-10 rounded-2xl bg-indigo-50 flex items-center justify-center text-indigo-600 font-bold overflow-hidden">
                {m.avatar ? <img src={m.avatar} className="w-full h-full object-cover" /> : m.name[0]}
              </div>
              <span className="text-[9px] font-bold uppercase bg-slate-100 px-2 py-1 rounded-lg text-slate-500">{m.religion || 'Religião'}</span>
            </div>
            <h4 className="font-bold text-slate-800 truncate">{m.name}</h4>
            <div className="flex flex-col gap-0.5 mt-1">
              <div className="flex items-center gap-1.5 text-xs text-slate-500">
                <Smartphone className="w-3 h-3 text-slate-300" />
                <span>{m.phone}</span>
              </div>
              <div className="flex items-center gap-1.5 text-xs text-slate-400">
                <Mail className="w-3 h-3 text-slate-300" />
                <span className="truncate">{m.email}</span>
              </div>
            </div>
            <p className="text-[10px] text-slate-400 mt-2 flex items-start gap-1">
              <MapPin className="w-3 h-3 shrink-0" />
              <span className="line-clamp-2">{m.address || 'Endereço não informado'}</span>
            </p>
            {m.interests && m.interests.length > 0 && (
              <div className="flex flex-wrap gap-1 mt-3">
                {m.interests.map((int, i) => (
                  <span key={i} className="px-2 py-0.5 bg-indigo-50 text-indigo-600 text-[9px] font-bold rounded-lg uppercase tracking-tight">{int}</span>
                ))}
              </div>
            )}
          </div>
          <div className="flex justify-between items-center pt-4 mt-4 border-t border-slate-50">
            <div className="flex flex-col">
              <span className="text-[9px] font-black text-slate-300 uppercase leading-none mb-1">Responsável</span>
              <span className="text-[10px] font-bold text-slate-500 truncate max-w-[100px]">{getLeaderName(m.responsible_leader_id)}</span>
            </div>
            <div className="flex gap-1">
              <button className="p-1.5 text-slate-300 hover:text-indigo-600" onClick={(e) => { e.stopPropagation(); setEditingMember(m); setIsMemberModalOpen(true); }}><Edit2 className="w-3.5 h-3.5" /></button>
              <button onClick={(e) => { e.stopPropagation(); setMembers(members.filter(mem => mem.id !== m.id)); }} className="p-1.5 text-slate-300 hover:text-red-600"><Trash2 className="w-3.5 h-3.5" /></button>
            </div>
          </div>
        </div>
      ))}
    </div>
  );

  const renderMemberListView = () => (
    <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden mx-6 mb-6 flex-1 flex flex-col">
      <div className="overflow-y-auto">
        <table className="w-full text-sm text-left">
          <thead className="bg-slate-50 text-slate-500 uppercase text-[10px] font-bold sticky top-0">
            <tr>
              <th className="px-6 py-4">Membro / Email</th>
              <th className="px-6 py-4">WhatsApp</th>
              <th className="px-6 py-4">Estágio / Interesses</th>
              <th className="px-6 py-4">Responsável</th>
              <th className="px-6 py-4 text-right">Ações</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {members.map(member => (
              <tr key={member.id} className="hover:bg-slate-50 transition-colors group cursor-pointer" onClick={() => { setEditingMember(member); setIsMemberModalOpen(true); }}>
                <td className="px-6 py-4">
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 rounded-lg bg-slate-100 flex items-center justify-center text-[10px] font-bold text-slate-500 uppercase overflow-hidden">
                      {member.avatar ? <img src={member.avatar} className="w-full h-full object-cover" /> : member.name[0]}
                    </div>
                    <div>
                      <p className="font-bold text-slate-800">{member.name}</p>
                      <p className="text-[10px] text-slate-400 truncate max-w-[200px] font-medium">{member.email}</p>
                    </div>
                  </div>
                </td>
                <td className="px-6 py-4 text-slate-600 font-medium">{member.phone}</td>
                <td className="px-6 py-4">
                  <div className="flex flex-col gap-1.5">
                    <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold uppercase self-start ${STAGES.find(s => s.id === member.stage)?.color}`}>
                      {STAGES.find(s => s.id === member.stage)?.label}
                    </span>
                    <div className="flex flex-wrap gap-1">
                      {member.interests?.map((int, i) => (
                        <span key={i} className="text-[9px] font-black text-slate-400 bg-slate-100 px-1.5 py-0.5 rounded uppercase tracking-tighter">{int}</span>
                      ))}
                    </div>
                  </div>
                </td>
                <td className="px-6 py-4">
                  <div className="flex items-center gap-2">
                    <div className="w-6 h-6 rounded-lg bg-slate-100 flex items-center justify-center text-[10px] font-bold text-slate-500 uppercase">{getLeaderName(member.responsible_leader_id)[0]}</div>
                    <span className="text-xs font-bold text-slate-600">{getLeaderName(member.responsible_leader_id)}</span>
                  </div>
                </td>
                <td className="px-6 py-4 text-right">
                  <div className="flex justify-end gap-2">
                    <button className="p-2 text-slate-400 hover:text-indigo-600 rounded-lg"><Edit2 className="w-4 h-4" /></button>
                    <button onClick={(e) => { e.stopPropagation(); setMembers(members.filter(m => m.id !== member.id)); }} className="p-2 text-slate-400 hover:text-red-600 rounded-lg"><Trash2 className="w-4 h-4" /></button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );

  const navItems = [
    { id: 'analytics', label: 'Dashboard', icon: <LayoutDashboard className="w-5 h-5" /> },
    { id: 'kanban', label: 'Pipeline', icon: <Columns className="w-5 h-5" /> },
    { id: 'contacts', label: 'Contatos', icon: <ContactIcon className="w-5 h-5" /> },
    { id: 'agenda', label: 'Agenda', icon: <CalendarDays className="w-5 h-5" /> },
    { id: 'team', label: 'Equipe', icon: <UsersIcon className="w-5 h-5" /> },
    { id: 'church', label: 'Igreja', icon: <ChurchIcon className="w-5 h-5" /> },
    { id: 'automation', label: 'Automação', icon: <Zap className="w-5 h-5" /> },
    { id: 'settings', label: 'Configurações', icon: <Settings className="w-5 h-5" /> },
  ];

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6 relative overflow-hidden font-sans">
        <div className="absolute top-0 left-0 w-full h-full pointer-events-none opacity-20">
          <div className="absolute top-[-10%] left-[-5%] w-[40%] h-[40%] bg-indigo-200 rounded-full blur-[120px]"></div>
          <div className="absolute bottom-[-10%] right-[-5%] w-[40%] h-[40%] bg-blue-200 rounded-full blur-[120px]"></div>
        </div>

        <div className="bg-white rounded-[48px] shadow-2xl w-full max-w-xl overflow-hidden relative z-10 flex flex-col md:flex-row border border-white">
          <div className="w-full md:w-[45%] bg-indigo-600 p-10 flex flex-col justify-between text-white relative">
            <div className="absolute top-0 left-0 w-full h-full overflow-hidden opacity-10">
               <div className="absolute top-10 left-10 w-40 h-40 border-8 border-white rounded-full"></div>
               <div className="absolute bottom-10 right-10 w-20 h-20 bg-white rounded-3xl rotate-45"></div>
            </div>
            <div className="relative z-10">
              <div className="w-14 h-14 bg-white/20 backdrop-blur-md rounded-2xl flex items-center justify-center mb-6 border border-white/30">
                <span className="font-black text-2xl">K</span>
              </div>
              <h1 className="text-4xl font-black leading-tight tracking-tighter">Koinonia<br/>Growth</h1>
            </div>
            <div className="relative z-10">
              <p className="text-indigo-100 text-sm font-medium leading-relaxed">
                {loginMode === 'login' 
                  ? 'Bem-vindo de volta à sua central de crescimento e liderança.' 
                  : 'Junte-se a centenas de igrejas que gerenciam o crescimento com amor e tecnologia.'}
              </p>
            </div>
          </div>

          <div className="flex-1 p-10 bg-white">
            <div className="flex bg-slate-100 p-1 rounded-2xl mb-8">
              <button onClick={() => setLoginMode('login')} className={`flex-1 py-2.5 text-xs font-black uppercase tracking-widest rounded-xl transition-all ${loginMode === 'login' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>Entrar</button>
              <button onClick={() => setLoginMode('register')} className={`flex-1 py-2.5 text-xs font-black uppercase tracking-widest rounded-xl transition-all ${loginMode === 'register' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>Cadastrar</button>
            </div>

            <form onSubmit={handleLogin} className="space-y-4 animate-in fade-in slide-in-from-bottom-2">
              {loginMode === 'register' && (
                <>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Nome Completo</label>
                    <div className="relative">
                      <User className="absolute left-4 top-3.5 w-4 h-4 text-slate-300" />
                      <input required placeholder="Como devemos te chamar?" className="w-full pl-12 pr-4 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:ring-2 focus:ring-indigo-100 transition-all text-slate-800 text-sm font-semibold" value={loginForm.name} onChange={e => setLoginForm({...loginForm, name: e.target.value})} />
                    </div>
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Sua Igreja</label>
                    <div className="relative">
                      <ChurchIcon className="absolute left-4 top-3.5 w-4 h-4 text-slate-300" />
                      <input required placeholder="Nome da comunidade" className="w-full pl-12 pr-4 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:ring-2 focus:ring-indigo-100 transition-all text-slate-800 text-sm font-semibold" value={loginForm.church} onChange={e => setLoginForm({...loginForm, church: e.target.value})} />
                    </div>
                  </div>
                </>
              )}

              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">E-mail</label>
                <div className="relative">
                  <Mail className="absolute left-4 top-3.5 w-4 h-4 text-slate-300" />
                  <input required type="email" placeholder="seu@email.com" className="w-full pl-12 pr-4 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:ring-2 focus:ring-indigo-100 transition-all text-slate-800 text-sm font-semibold" value={loginForm.email} onChange={e => setLoginForm({...loginForm, email: e.target.value})} />
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Senha</label>
                <div className="relative">
                  <Lock className="absolute left-4 top-3.5 w-4 h-4 text-slate-300" />
                  <input required type={showPassword ? "text" : "password"} placeholder="••••••••" className="w-full pl-12 pr-12 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:ring-2 focus:ring-indigo-100 transition-all text-slate-800 text-sm font-semibold" value={loginForm.password} onChange={e => setLoginForm({...loginForm, password: e.target.value})} />
                  <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-4 top-3.5 text-slate-300 hover:text-slate-500">
                    {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                  </button>
                </div>
              </div>

              <button type="submit" className="w-full py-4 bg-indigo-600 text-white font-black rounded-[20px] mt-6 shadow-xl shadow-indigo-100 hover:bg-indigo-700 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-2">
                {loginMode === 'login' ? 'Acessar Plataforma' : 'Criar minha conta'}
                <ArrowRight className="w-5 h-5" />
              </button>
            </form>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className={`flex h-screen overflow-hidden ${theme === 'dark' ? 'bg-slate-950 text-slate-100' : 'bg-slate-50 text-slate-800'}`}>
      <aside className={`${theme === 'dark' ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'} border-r transition-all duration-300 flex flex-col ${isSidebarOpen ? 'w-64' : 'w-20'}`}>
        <div className="p-6 flex items-center gap-3">
          <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white font-bold text-xl shadow-lg">K</div>
          {isSidebarOpen && <div className="flex flex-col"><span className={`font-bold leading-tight ${theme === 'dark' ? 'text-white' : 'text-slate-800'}`}>Koinonia</span><span className="text-[10px] text-slate-400 uppercase font-bold tracking-tighter">Growth CRM</span></div>}
        </div>
        <nav className="flex-1 mt-6 px-3 space-y-1 overflow-y-auto">
          {navItems.map((item) => (
            <button key={item.id} onClick={() => setActiveTab(item.id as any)} className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl transition-all ${activeTab === item.id ? 'bg-indigo-50 text-indigo-700 font-semibold' : 'text-slate-500 hover:bg-slate-50 hover:text-slate-800'}`}>
              <div className={activeTab === item.id ? 'text-indigo-600' : 'text-slate-400'}>{item.icon}</div>
              {isSidebarOpen && <span>{item.label}</span>}
            </button>
