                    onChange={e => setEditingTeamMember({...editingTeamMember, role: e.target.value as UserRole})}
                    className="w-full pl-10 pr-10 py-3.5 bg-slate-100 rounded-xl font-bold text-slate-800 border-none outline-none focus:ring-2 focus:ring-indigo-100 appearance-none cursor-pointer"
                  >
