  Contact as ContactIcon,
  CheckCircle,
  Plus,
  ArrowRight,
  Key,
  Globe,
  Palette,
  Clock,
  HelpCircle,
  ShieldCheck,
  Smartphone,
  List,
  LayoutGrid,
  MapPin,
  Upload,
  UserPlus,
  Edit2,
  Lock,
  CalendarDays,
  Mail,
  Eye,
  EyeOff,
  Tag,
  Shield,
  Briefcase,
  Camera,
  Languages,
  MailWarning,
  KeyRound,
  LifeBuoy,
  Info,
  Download
} from 'lucide-react';
import KanbanBoard from './components/KanbanBoard';
import AnalyticsDashboard from './components/AnalyticsDashboard';
import AutomationSettings from './components/AutomationSettings';
import ScheduleModule from './components/ScheduleModule';
import { INITIAL_MEMBERS, INITIAL_EVENTS, INTEGRATIONS, STAGES } from './constants';
import { Member, MemberStage, SystemUser, UserRole, ScheduleEvent } from './types';
import { KoinoniaDB } from './services/db';

const TIMEZONES = [
  "(GMT-03:00) Brasília / São Paulo",
  "(GMT-04:00) Manaus / Campo Grande",
  "(GMT-05:00) Rio Branco",
  "(GMT-00:00) London / Lisbon",
  "(GMT+01:00) Paris / Berlin",
  "(GMT-05:00) New York / Miami"
];

const LANGUAGES = [
  { id: 'pt-BR', label: 'Português (Brasil)' },
  { id: 'en-US', label: 'English (US)' },
  { id: 'es-ES', label: 'Español' }
];

const AVAILABLE_PERMISSIONS = [
  { id: 'view_dashboard', label: 'Ver Dashboard' },
  { id: 'manage_pipeline', label: 'Gerir Pipeline' },
  { id: 'manage_contacts', label: 'Gerir Contatos' },
  { id: 'manage_team', label: 'Gerir Equipe' },
  { id: 'manage_church', label: 'Configurar Igreja' },
  { id: 'manage_settings', label: 'Acesso às Configurações' }
];

const App: React.FC = () => {
  // Global App State
  const [theme, setTheme] = useState<'light' | 'dark'>('light');
  const [viewMode, setViewMode] = useState<'blocks' | 'list'>('list');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loginMode, setLoginMode] = useState<'login' | 'register'>('login');
  const [showPassword, setShowPassword] = useState(false);
  const [activeTab, setActiveTab] = useState<'analytics' | 'kanban' | 'automation' | 'team' | 'church' | 'contacts' | 'settings' | 'agenda'>('analytics');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isProfileOpen, setIsProfileOpen] = useState(false);

  // Auth & Data State
  const [currentUser, setCurrentUser] = useState<SystemUser | null>(null);
  const [teamMembers, setTeamMembers] = useState<SystemUser[]>([]);
  const [members, setMembers] = useState<Member[]>([]);
  const [events, setEvents] = useState<ScheduleEvent[]>([]);

  // Church & Settings State
  const [churchData, setChurchData] = useState({ 
    logo: '', 
    name: '', 
    email: '', 
    cep: '', 
    address: '', 
    city: '', 
    state: '', 
    pastor: '' 
  });
  const [timezone, setTimezone] = useState(TIMEZONES[0]);
  const [language, setLanguage] = useState(LANGUAGES[0].id);
  const [pushEnabled, setPushEnabled] = useState(true);
  const [emailAlertsEnabled, setEmailAlertsEnabled] = useState(true);
  const [newPassword, setNewPassword] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const memberFileInputRef = useRef<HTMLInputElement>(null);
  const userAvatarInputRef = useRef<HTMLInputElement>(null);

  const APP_VERSION = "2.4.0-stable";

  // Persistence Logic - Load Data
  useEffect(() => {
    const loadedMembers = KoinoniaDB.getAllMembers();
    const loadedEvents = KoinoniaDB.getAllEvents();
    const loadedTeam = KoinoniaDB.getTeamMembers();
    const loadedChurch = KoinoniaDB.getChurchData();

    setMembers(loadedMembers);
    setEvents(loadedEvents);
    setTeamMembers(loadedTeam);
    if (loadedChurch) setChurchData(loadedChurch);

    const savedUser = localStorage.getItem('koinonia_session');
    if (savedUser) {
      setCurrentUser(JSON.parse(savedUser));
      setIsLoggedIn(true);
    }
  }, []);

  // Persistence Logic - Save Data on Change
  useEffect(() => { if (members.length > 0) KoinoniaDB.saveMembers(members); }, [members]);
  useEffect(() => { if (events.length > 0) KoinoniaDB.saveEvents(events); }, [events]);
  useEffect(() => { if (teamMembers.length > 0) KoinoniaDB.saveTeamMembers(teamMembers); }, [teamMembers]);
  useEffect(() => { if (churchData.name) KoinoniaDB.saveChurchData(churchData); }, [churchData]);

  // Modal States
  const [isMemberModalOpen, setIsMemberModalOpen] = useState(false);
  const [editingMember, setEditingMember] = useState<Partial<Member> | null>(null);
  const [isTeamModalOpen, setIsTeamModalOpen] = useState(false);
  const [editingTeamMember, setEditingTeamMember] = useState<Partial<SystemUser> | null>(null);
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);

  const [loginForm, setLoginForm] = useState({ name: '', email: '', whatsapp: '', church: '', password: '' });

  // Core Actions
  const moveMember = (id: string, nextStage: MemberStage) => {
    setMembers(prev => prev.map(m => m.id === id ? { ...m, stage: nextStage } : m));
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const newUser: SystemUser = {
      id: Math.random().toString(36).substr(2, 9),
      name: loginForm.name || 'Usuário Koinonia',
      email: loginForm.email || 'usuario@koinonia.com',
      whatsapp: loginForm.whatsapp,
      role: UserRole.ADMIN,
      church_id: loginForm.church || 'Igreja Central',
      permissions: AVAILABLE_PERMISSIONS.map(p => p.id),
      avatar: ''
    };

    setCurrentUser(newUser);
    if (!teamMembers.find(t => t.email === newUser.email)) {
        setTeamMembers(prev => [...prev, newUser]);
    }

    setChurchData(prev => ({ ...prev, name: newUser.church_id, pastor: newUser.name }));
    localStorage.setItem('koinonia_session', JSON.stringify(newUser));
    setIsLoggedIn(true);
  };

  const handleLogout = () => {
    localStorage.removeItem('koinonia_session');
    setIsLoggedIn(false);
    setCurrentUser(null);
  };

  const handleCepBlur = async (cep: string) => {
    const cleanCep = cep.replace(/\D/g, '');
    if (cleanCep.length === 8) {
      try {
        const response = await fetch(`https://viacep.com.br/ws/${cleanCep}/json/`);
        const data = await response.json();
        if (!data.erro) {
          setChurchData(prev => ({
            ...prev,
            address: `${data.logradouro}, ${data.bairro}`,
            city: data.localidade,
            state: data.uf
          }));
        }
      } catch (error) { console.error("Erro CEP:", error); }
    }
  };

  const handleMemberCepBlur = async (cep: string) => {
    const cleanCep = cep.replace(/\D/g, '');
    if (cleanCep.length === 8) {
      try {
        const response = await fetch(`https://viacep.com.br/ws/${cleanCep}/json/`);
        const data = await response.json();
        if (!data.erro) {
          setEditingMember(prev => prev ? ({
            ...prev,
            address: `${data.logradouro}, ${data.bairro}, ${data.localidade} - ${data.uf}`
          }) : null);
        }
      } catch (error) { console.error("Erro CEP Contato:", error); }
    }
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setChurchData({ ...churchData, logo: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleMemberAvatarUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setEditingMember(prev => prev ? ({ ...prev, avatar: reader.result as string }) : null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleUserAvatarUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setCurrentUser(prev => prev ? ({ ...prev, avatar: reader.result as string }) : null);
      };
