                  <select 
                    value={editingMember?.responsible_leader_id || currentUser?.id || ''} 
                    onChange={e => setEditingMember({...editingMember, responsible_leader_id: e.target.value})}
                    className="w-full pl-10 pr-10 py-3.5 bg-slate-50 rounded-xl font-bold text-slate-800 border-none outline-none focus:ring-2 focus:ring-indigo-100 appearance-none cursor-pointer"
                  >
                    {teamMembers.map(leader => (
