                      <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Nome Completo</label>
                      <div className="relative"><User className="absolute left-3 top-3 w-4 h-4 text-slate-300" /><input required value={editingMember?.name || ''} onChange={e => setEditingMember({...editingMember, name: e.target.value})} className="w-full pl-10 pr-3 py-3 bg-slate-50 rounded-xl font-bold text-slate-800 border-none outline-none focus:ring-2 focus:ring-indigo-100" /></div>
                    </div>
                    <div className="space-y-1">
                      <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">WhatsApp</label>
                      <div className="relative"><Smartphone className="absolute left-3 top-3 w-4 h-4 text-slate-300" /><input required value={editingMember?.phone || ''} onChange={e => setEditingMember({...editingMember, phone: e.target.value})} className="w-full pl-10 pr-3 py-3 bg-slate-50 rounded-xl text-slate-800 border-none outline-none focus:ring-2 focus:ring-indigo-100" /></div>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-1">
                      <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">E-mail</label>
                      <div className="relative"><Mail className="absolute left-3 top-3 w-4 h-4 text-slate-300" /><input required type="email" value={editingMember?.email || ''} onChange={e => setEditingMember({...editingMember, email: e.target.value})} className="w-full pl-10 pr-3 py-3 bg-slate-50 rounded-xl text-slate-800 border-none outline-none focus:ring-2 focus:ring-indigo-100" /></div>
                    </div>
                    <div className="space-y-1">
                      <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">CEP (Busca Automática)</label>
                      <div className="relative"><Search className="absolute left-3 top-3 w-4 h-4 text-slate-300" /><input placeholder="00000-000" value={editingMember?.cep || ''} onChange={e => setEditingMember({...editingMember, cep: e.target.value})} onBlur={e => handleMemberCepBlur(e.target.value)} className="w-full pl-10 pr-3 py-3 bg-slate-50 rounded-xl text-slate-800 border-none outline-none focus:ring-2 focus:ring-indigo-100" /></div>
                    </div>
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Religião</label><input value={editingMember?.religion || ''} onChange={e => setEditingMember({...editingMember, religion: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl text-slate-800 border-none outline-none focus:ring-2 focus:ring-indigo-100" /></div>
                <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Sexo</label><select value={editingMember?.gender || ''} onChange={e => setEditingMember({...editingMember, gender: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl font-bold text-slate-700 border-none outline-none focus:ring-2 focus:ring-indigo-100"><option value="">Selecione</option><option value="Masculino">Masculino</option><option value="Feminino">Feminino</option></select></div>
                <div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Origem (Canal)</label><input value={editingMember?.channel || ''} onChange={e => setEditingMember({...editingMember, channel: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl font-bold text-slate-800 border-none outline-none focus:ring-2 focus:ring-indigo-100 placeholder:text-slate-300" placeholder="Ex: Instagram, Indicação..." /></div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Interesses (separados por vírgula)</label>
                <div className="relative"><Tag className="absolute left-3 top-3 w-4 h-4 text-slate-300" /><input placeholder="Ex: Música, Jovens, Casais..." value={editingMember?.interests?.join(', ') || ''} onChange={e => setEditingMember({...editingMember, interests: e.target.value.split(',').map(s => s.trim())})} className="w-full pl-10 pr-3 py-3 bg-slate-50 rounded-xl text-slate-800 border-none outline-none focus:ring-2 focus:ring-indigo-100" /></div>
