            </div>
            <span className="text-xs font-black text-slate-400 uppercase tracking-tighter capitalize">{monthName}</span>
          </div>

          <div className="flex-1 overflow-y-auto p-8 space-y-6">
            {events.filter(e => e.start_date.getMonth() === viewDate.getMonth() && e.start_date.getFullYear() === viewDate.getFullYear()).length > 0 ? 
              events
                .filter(e => e.start_date.getMonth() === viewDate.getMonth() && e.start_date.getFullYear() === viewDate.getFullYear())
                .sort((a,b) => a.start_date.getTime() - b.start_date.getTime())
                .map(event => (
              <div key={event.id} className="group relative pl-8 before:absolute before:left-0 before:top-0 before:bottom-0 before:w-1 before:bg-slate-100 before:rounded-full hover:before:bg-indigo-600 transition-all">
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                  <div className="space-y-1 flex-1">
                    <div className="flex items-center gap-3">
                      <span className={`px-2 py-0.5 rounded-lg text-[9px] font-black uppercase border ${getEventTypeStyle(event.type)}`}>
                        {getEventTypeLabel(event.type)}
                      </span>
                      <h4 className="font-black text-slate-800 group-hover:text-indigo-600 transition-colors">{event.title}</h4>
                    </div>
                    <p className="text-sm text-slate-500 font-medium line-clamp-1">{event.description}</p>
                    <div className="flex flex-wrap gap-4 pt-2">
                      <div className="flex items-center gap-1.5 text-xs text-slate-400 font-bold">
                        <Clock className="w-3.5 h-3.5" />
                        {event.start_date.toLocaleDateString('pt-BR', {day: '2-digit', month: '2-digit'})} | {event.start_date.toLocaleTimeString('pt-BR', {hour: '2-digit', minute: '2-digit'})}
                      </div>
                      <div className="flex items-center gap-1.5 text-xs text-slate-400 font-bold">
                        <MapPin className="w-3.5 h-3.5" />
                        {event.location}
                      </div>
                      {event.responsible_id && (
                        <div className="flex items-center gap-1.5 text-xs text-indigo-400 font-bold">
                          <UserIcon className="w-3.5 h-3.5" />
                          Responsável atribuído
                        </div>
                      )}
                    </div>
                  </div>
                  <button className="p-2 text-slate-300 hover:text-slate-600 hover:bg-slate-50 rounded-xl transition-all self-start md:self-center">
                    <MoreHorizontal className="w-5 h-5" />
                  </button>
                </div>
              </div>
            )) : (
              <div className="h-full flex flex-col items-center justify-center text-slate-400 gap-4 opacity-50">
                <CalendarIcon className="w-12 h-12" />
                <p className="font-bold text-sm uppercase tracking-widest text-center">Nenhum evento agendado para este período</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

