                  <select 
                    value={editingTeamMember?.role || UserRole.LEADER} 
                    onChange={e => setEditingTeamMember({...editingTeamMember, role: e.target.value as UserRole})}
                    className="w-full pl-10 pr-10 py-3.5 bg-slate-100 rounded-xl font-bold text-slate-800 border-none outline-none focus:ring-2 focus:ring-indigo-100 appearance-none cursor-pointer"
                  >
                    <option value={UserRole.PASTOR}>Pastor</option>
                    <option value={UserRole.LEADER}>Líder</option>
                    <option value={UserRole.RECEPTION}>Recepção</option>
                    <option value={UserRole.VOLUNTEER}>Voluntário</option>
                    <option value={UserRole.ADMIN}>Administrador</option>
                  </select>
                  <ChevronRight className="absolute right-4 top-3.5 w-4 h-4 text-slate-300 rotate-90 pointer-events-none" />
