  { id: 'view_dashboard', label: 'Ver Dashboard' },
  { id: 'manage_pipeline', label: 'Gerir Pipeline' },
  { id: 'manage_contacts', label: 'Gerir Contatos' },
  { id: 'manage_team', label: 'Gerir Equipe' },
  { id: 'manage_church', label: 'Configurar Igreja' },
  { id: 'manage_settings', label: 'Acesso às Configurações' }
];

// Definition of navigation items for the sidebar
const navItems = [
  { id: 'analytics', label: 'Analytics', icon: <LayoutDashboard className="w-5 h-5" /> },
  { id: 'kanban', label: 'Pipeline', icon: <Columns className="w-5 h-5" /> },
  { id: 'agenda', label: 'Agenda', icon: <CalendarDays className="w-5 h-5" /> },
  { id: 'contacts', label: 'Contatos', icon: <ContactIcon className="w-5 h-5" /> },
