                    <ChevronRight className="absolute right-4 top-3.5 w-4 h-4 text-slate-300 rotate-90 pointer-events-none" />
                  </div>
                </div>
                {editingMember?.id && (
                  <div className="flex items-end">
                    <button 
                      type="button"
                      onClick={() => openAddEventModal(new Date(), editingMember.id)}
                      className="w-full py-3.5 bg-amber-50 text-amber-700 font-bold rounded-xl hover:bg-amber-100 transition-all flex items-center justify-center gap-2 border border-amber-200"
                    >
                      <CalendarPlus className="w-4 h-4" /> Agendar Atividade
                    </button>
                  </div>
                )}
              </div>

              <button type="submit" className="w-full py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 active:scale-95 transition-all mt-4">
                Salvar Registro Completo
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Event Modal */}
      {isEventModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[110] flex items-center justify-center p-4">
          <div className="bg-white rounded-[40px] w-full max-w-md shadow-2xl overflow-hidden animate-in zoom-in duration-300">
            <div className="p-6 bg-indigo-600 text-white flex justify-between items-center">
              <h3 className="font-bold">Novo Agendamento</h3>
              <button onClick={() => setIsEventModalOpen(false)}><X className="w-5 h-5" /></button>
            </div>
            <form onSubmit={handleSaveEvent} className="p-6 space-y-4">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase">Título</label>
                <input required value={newEvent.title} onChange={e => setNewEvent({...newEvent, title: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl border-none outline-none focus:ring-2 focus:ring-indigo-100 font-bold" placeholder="Ex: Visita de Boas-vindas" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase">Categoria</label>
                <select value={newEvent.type} onChange={e => setNewEvent({...newEvent, type: e.target.value as EventType})} className="w-full p-3 bg-slate-50 rounded-xl border-none outline-none focus:ring-2 focus:ring-indigo-100 font-bold">
                  <option value={EventType.MEETING}>Reunião</option>
                  <option value={EventType.VISIT}>Visita</option>
                  <option value={EventType.FOLLOW_UP}>Acompanhamento</option>
                  <option value={EventType.EVENT}>Evento</option>
                  <option value={EventType.SERVICE}>Culto</option>
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase">Responsável pela Execução</label>
                <div className="relative">
                  <User className="absolute left-3 top-3.5 w-4 h-4 text-slate-300 z-10" />
                  <select 
                    required
                    value={newEvent.responsible_id || ''} 
                    onChange={e => setNewEvent({...newEvent, responsible_id: e.target.value})}
                    className="w-full pl-10 pr-3 py-3 bg-slate-50 rounded-xl border-none outline-none focus:ring-2 focus:ring-indigo-100 font-bold appearance-none"
                  >
                    <option value="">Selecione um Responsável</option>
                    {teamMembers.map(leader => (
                      <option key={leader.id} value={leader.id}>{leader.name}</option>
                    ))}
                  </select>
                  <ChevronRight className="absolute right-4 top-3.5 w-4 h-4 text-slate-300 rotate-90 pointer-events-none" />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Início</label>
                  <input type="datetime-local" value={formatDateForInput(newEvent.start_date)} onChange={e => setNewEvent({...newEvent, start_date: new Date(e.target.value)})} className="w-full p-3 bg-slate-50 rounded-xl border-none outline-none focus:ring-2 focus:ring-indigo-100 text-xs font-bold" />
                </div>
                <div className="space-y-1">
