import React, { useState } from 'react';
import { 
  Calendar as CalendarIcon, 
  Clock, 
  MapPin, 
  Plus, 
  ChevronLeft, 
  ChevronRight, 
  MoreHorizontal,
  CalendarDays,
  User as UserIcon
} from 'lucide-react';
import { ScheduleEvent, EventType, SystemUser } from '../types';

interface ScheduleModuleProps {
  events: ScheduleEvent[];
  team?: SystemUser[];
  onAddEvent?: (date?: Date) => void;
}

const ScheduleModule: React.FC<ScheduleModuleProps> = ({ events, team = [], onAddEvent }) => {
  const [viewDate, setViewDate] = useState(new Date());

  const getEventTypeStyle = (type: EventType) => {
    switch (type) {
      case EventType.SERVICE: return 'bg-indigo-100 text-indigo-700 border-indigo-200';
      case EventType.MEETING: return 'bg-amber-100 text-amber-700 border-amber-200';
      case EventType.EVENT: return 'bg-purple-100 text-purple-700 border-purple-200';
      case EventType.FOLLOW_UP: return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      case EventType.VISIT: return 'bg-rose-100 text-rose-700 border-rose-200';
      default: return 'bg-slate-100 text-slate-700 border-slate-200';
    }
  };

  const getEventTypeLabel = (type: EventType) => {
    switch (type) {
      case EventType.SERVICE: return 'Culto';
      case EventType.MEETING: return 'Reunião';
      case EventType.EVENT: return 'Evento';
      case EventType.FOLLOW_UP: return 'Acompanhamento';
      case EventType.VISIT: return 'Visita';
      default: return 'Geral';
    }
  };

  const getResponsibleName = (id?: string) => {
    if (!id) return null;
    return team.find(t => t.id === id)?.name || 'Responsável não encontrado';
  };

  const nextMonth = () => {
    setViewDate(new Date(viewDate.getFullYear(), viewDate.getMonth() + 1, 1));
  };

  const prevMonth = () => {
    setViewDate(new Date(viewDate.getFullYear(), viewDate.getMonth() - 1, 1));
  };

  const monthName = viewDate.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' });

  const daysInMonth = new Date(viewDate.getFullYear(), viewDate.getMonth() + 1, 0).getDate();
  const firstDayOfMonth = new Date(viewDate.getFullYear(), viewDate.getMonth(), 1).getDay();
  const calendarDays = Array.from({ length: 42 }, (_, i) => {
    const day = i - firstDayOfMonth + 1;
    return day > 0 && day <= daysInMonth ? day : null;
  });

  const isToday = (day: number | null) => {
    if (!day) return false;
    const now = new Date();
    return now.getDate() === day && now.getMonth() === viewDate.getMonth() && now.getFullYear() === viewDate.getFullYear();
  };

  const hasEventOnDay = (day: number | null) => {
    if (!day) return false;
    return events.some(e => {
      const d = new Date(e.start_date);
      return d.getDate() === day && d.getMonth() === viewDate.getMonth() && d.getFullYear() === viewDate.getFullYear();
    });
  };

  return (
    <div className="p-8 h-full overflow-hidden flex flex-col gap-8 bg-slate-50/50">
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-3xl font-black text-slate-800">Agenda do Reino</h2>
          <p className="text-slate-500 font-medium">Gestão de cultos, reuniões e eventos da comunidade.</p>
        </div>
        <button 
          onClick={() => onAddEvent?.()}
          className="flex items-center gap-2 px-6 py-3 bg-indigo-600 text-white rounded-2xl font-bold hover:bg-indigo-700 shadow-xl shadow-indigo-200 transition-all active:scale-95"
        >
          <Plus className="w-5 h-5" /> Novo Evento
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 flex-1 overflow-hidden">
        <div className="lg:col-span-4 flex flex-col gap-6 overflow-y-auto">
          <div className="bg-white p-6 rounded-[40px] border border-slate-100 shadow-sm">
            <div className="flex justify-between items-center mb-6">
              <h3 className="font-black text-slate-800 uppercase text-xs tracking-widest capitalize">{monthName}</h3>
              <div className="flex gap-1">
                <button onClick={prevMonth} className="p-1.5 hover:bg-slate-50 rounded-lg text-slate-400"><ChevronLeft className="w-4 h-4" /></button>
                <button onClick={nextMonth} className="p-1.5 hover:bg-slate-50 rounded-lg text-slate-400"><ChevronRight className="w-4 h-4" /></button>
              </div>
            </div>
            <div className="grid grid-cols-7 gap-1 text-center mb-2">
              {['D','S','T','Q','Q','S','S'].map(d => <span key={d} className="text-[10px] font-black text-slate-300">{d}</span>)}
            </div>
            <div className="grid grid-cols-7 gap-1 text-center">
              {calendarDays.map((day, i) => (
                <button 
                  key={i} 
                  disabled={!day}
                  onClick={() => day && onAddEvent?.(new Date(viewDate.getFullYear(), viewDate.getMonth(), day))}
                  className={`aspect-square flex flex-col items-center justify-center text-xs font-bold rounded-xl transition-all relative ${day ? 'hover:bg-indigo-50 text-slate-500 cursor-pointer' : 'opacity-0'} ${isToday(day) ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : ''}`}
                >
                  {day}
                  {hasEventOnDay(day) && (
                    <span className={`absolute bottom-1 w-1 h-1 rounded-full ${isToday(day) ? 'bg-white' : 'bg-indigo-400'}`}></span>
                  )}
                </button>
              ))}
            </div>
          </div>

          <div className="bg-white p-6 rounded-[40px] border border-slate-100 shadow-sm">
            <h3 className="font-black text-slate-800 uppercase text-xs tracking-widest mb-4">Categorias</h3>
            <div className="space-y-3">
              {Object.values(EventType).map(type => (
                <label key={type} className="flex items-center gap-3 cursor-pointer group">
                  <div className={`w-3 h-3 rounded-full ${getEventTypeStyle(type).split(' ')[0]}`} />
                  <span className="text-sm font-bold text-slate-600 group-hover:text-indigo-600 transition-colors">{getEventTypeLabel(type)}</span>
                  <input type="checkbox" defaultChecked className="ml-auto rounded border-slate-200 text-indigo-600" />
                </label>
              ))}
            </div>
          </div>
        </div>

        <div className="lg:col-span-8 bg-white rounded-[40px] border border-slate-100 shadow-sm flex flex-col overflow-hidden">
          <div className="p-8 border-b border-slate-50 flex justify-between items-center bg-slate-50/30">
            <div className="flex items-center gap-3">
              <CalendarDays className="w-6 h-6 text-indigo-600" />
              <h3 className="text-lg font-black text-slate-800">Compromissos do Mês</h3>
            </div>
            <span className="text-xs font-black text-slate-400 uppercase tracking-tighter capitalize">{monthName}</span>
          </div>

          <div className="flex-1 overflow-y-auto p-8 space-y-6">
            {events.filter(e => e.start_date.getMonth() === viewDate.getMonth() && e.start_date.getFullYear() === viewDate.getFullYear()).length > 0 ? 
              events
                .filter(e => e.start_date.getMonth() === viewDate.getMonth() && e.start_date.getFullYear() === viewDate.getFullYear())
                .sort((a,b) => a.start_date.getTime() - b.start_date.getTime())
                .map(event => (
              <div key={event.id} className="group relative pl-8 before:absolute before:left-0 before:top-0 before:bottom-0 before:w-1 before:bg-slate-100 before:rounded-full hover:before:bg-indigo-600 transition-all">
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                  <div className="space-y-1 flex-1">
                    <div className="flex items-center gap-3">
                      <span className={`px-2 py-0.5 rounded-lg text-[9px] font-black uppercase border ${getEventTypeStyle(event.type)}`}>
                        {getEventTypeLabel(event.type)}
                      </span>
                      <h4 className="font-black text-slate-800 group-hover:text-indigo-600 transition-colors">{event.title}</h4>
                    </div>
                    <p className="text-sm text-slate-500 font-medium line-clamp-1">{event.description}</p>
                    <div className="flex flex-wrap gap-4 pt-2">
                      <div className="flex items-center gap-1.5 text-xs text-slate-400 font-bold">
                        <Clock className="w-3.5 h-3.5" />
                        {event.start_date.toLocaleDateString('pt-BR', {day: '2-digit', month: '2-digit'})} | {event.start_date.toLocaleTimeString('pt-BR', {hour: '2-digit', minute: '2-digit'})}
                      </div>
                      <div className="flex items-center gap-1.5 text-xs text-slate-400 font-bold">
                        <MapPin className="w-3.5 h-3.5" />
                        {event.location}
                      </div>
                      {event.responsible_id && (
                        <div className="flex items-center gap-1.5 text-xs text-indigo-400 font-bold">
                          <UserIcon className="w-3.5 h-3.5" />
                          Responsável: <span className="text-indigo-600">{getResponsibleName(event.responsible_id)}</span>
                        </div>
                      )}
                    </div>
                  </div>
                  <button className="p-2 text-slate-300 hover:text-slate-600 hover:bg-slate-50 rounded-xl transition-all self-start md:self-center">
                    <MoreHorizontal className="w-5 h-5" />
                  </button>
                </div>
              </div>
            )) : (
              <div className="h-full flex flex-col items-center justify-center text-slate-400 gap-4 opacity-50">
                <CalendarIcon className="w-12 h-12" />
                <p className="font-bold text-sm uppercase tracking-widest text-center">Nenhum evento agendado para este período</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ScheduleModule;

