  { id: 'manage_team', label: 'Gerir Equipe' },
  { id: 'manage_church', label: 'Configurar Igreja' },
  { id: 'manage_settings', label: 'Acesso às Configurações' }
];

const navItems = [
  { id: 'analytics', label: 'Analytics', icon: <LayoutDashboard className="w-5 h-5" /> },
  { id: 'kanban', label: 'Pipeline', icon: <Columns className="w-5 h-5" /> },
  { id: 'agenda', label: 'Agenda', icon: <CalendarDays className="w-5 h-5" /> },
  { id: 'contacts', label: 'Contatos', icon: <ContactIcon className="w-5 h-5" /> },
  { id: 'automation', label: 'Automação', icon: <Zap className="w-5 h-5" /> },
  { id: 'team', label: 'Equipe', icon: <UsersIcon className="w-5 h-5" /> },
  { id: 'church', label: 'Igreja', icon: <ChurchIcon className="w-5 h-5" /> },
  { id: 'settings', label: 'Ajustes', icon: <Settings className="w-5 h-5" /> },
];

const App: React.FC = () => {
  const [theme, setTheme] = useState<'light' | 'dark'>('light');
  const [viewMode, setViewMode] = useState<'blocks' | 'list'>('list');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loginMode, setLoginMode] = useState<'login' | 'register'>('login');
  const [showPassword, setShowPassword] = useState(false);
  const [activeTab, setActiveTab] = useState<'analytics' | 'kanban' | 'automation' | 'team' | 'church' | 'contacts' | 'settings' | 'agenda'>('analytics');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isProfileOpen, setIsProfileOpen] = useState(false);

  const [currentUser, setCurrentUser] = useState<SystemUser | null>(null);
  const [teamMembers, setTeamMembers] = useState<SystemUser[]>([]);
  const [members, setMembers] = useState<Member[]>([]);
  const [events, setEvents] = useState<ScheduleEvent[]>([]);

  const [churchData, setChurchData] = useState({ 
    logo: '', 
    name: '', 
    email: '', 
    cep: '', 
    address: '', 
    city: '', 
    state: '', 
    pastor: '' 
  });
  const [timezone, setTimezone] = useState(TIMEZONES[0]);
  const [language, setLanguage] = useState(LANGUAGES[0].id);
  const [pushEnabled, setPushEnabled] = useState(true);
  const [emailAlertsEnabled, setEmailAlertsEnabled] = useState(true);
  const [newPassword, setNewPassword] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const memberFileInputRef = useRef<HTMLInputElement>(null);
  const userAvatarInputRef = useRef<HTMLInputElement>(null);
  const searchTimeoutRef = useRef<number | null>(null);

  const APP_VERSION = "2.4.0-stable";

  useEffect(() => {
    const loadedMembers = KoinoniaDB.getAllMembers();
    const loadedEvents = KoinoniaDB.getAllEvents();
    const loadedTeam = KoinoniaDB.getTeamMembers();
    const loadedChurch = KoinoniaDB.getChurchData();

    setMembers(loadedMembers);
    setEvents(loadedEvents);
    setTeamMembers(loadedTeam);
    if (loadedChurch) setChurchData(loadedChurch);

    const savedUser = localStorage.getItem('koinonia_session');
    if (savedUser) {
      setCurrentUser(JSON.parse(savedUser));
      setIsLoggedIn(true);
    }
  }, []);

  useEffect(() => { if (members.length > 0) KoinoniaDB.saveMembers(members); }, [members]);
  useEffect(() => { if (events.length > 0) KoinoniaDB.saveEvents(events); }, [events]);
  useEffect(() => { if (teamMembers.length > 0) KoinoniaDB.saveTeamMembers(teamMembers); }, [teamMembers]);
  useEffect(() => { if (churchData.name) KoinoniaDB.saveChurchData(churchData); }, [churchData]);

  const [isMemberModalOpen, setIsMemberModalOpen] = useState(false);
  const [editingMember, setEditingMember] = useState<Partial<Member> | null>(null);
  const [isTeamModalOpen, setIsTeamModalOpen] = useState(false);
  const [editingTeamMember, setEditingTeamMember] = useState<Partial<SystemUser> | null>(null);
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const [isEventModalOpen, setIsEventModalOpen] = useState(false);
  const [newEvent, setNewEvent] = useState<Partial<ScheduleEvent>>({
    title: '',
    type: EventType.MEETING,
    start_date: new Date(),
    end_date: new Date(new Date().getTime() + 3600000),
    responsible_id: ''
  });

  const [locationSuggestions, setLocationSuggestions] = useState<any[]>([]);
  const [showLocationSuggestions, setShowLocationSuggestions] = useState(false);
  const [isSearchingLocation, setIsSearchingLocation] = useState(false);

  const [loginForm, setLoginForm] = useState({ name: '', email: '', whatsapp: '', church: '', password: '' });

  const moveMember = (id: string, nextStage: MemberStage) => {
    setMembers(prev => prev.map(m => m.id === id ? { ...m, stage: nextStage } : m));
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const newUser: SystemUser = {
      id: Math.random().toString(36).substr(2, 9),
      name: loginForm.name || 'Usuário Koinonia',
      email: loginForm.email || 'usuario@koinonia.com',
      whatsapp: loginForm.whatsapp,
      role: UserRole.ADMIN,
      church_id: loginForm.church || 'Igreja Central',
      permissions: AVAILABLE_PERMISSIONS.map(p => p.id),
      avatar: ''
    };

    setCurrentUser(newUser);
    if (!teamMembers.find(t => t.email === newUser.email)) {
        setTeamMembers(prev => [...prev, newUser]);
    }

    setChurchData(prev => ({ ...prev, name: newUser.church_id, pastor: newUser.name }));
    localStorage.setItem('koinonia_session', JSON.stringify(newUser));
    setIsLoggedIn(true);
  };

  const handleLogout = () => {
    localStorage.removeItem('koinonia_session');
    setIsLoggedIn(false);
    setCurrentUser(null);
  };

  const handleCepBlur = async (cep: string) => {
    const cleanCep = cep.replace(/\D/g, '');
    if (cleanCep.length === 8) {
      try {
        const response = await fetch(`https://viacep.com.br/ws/${cleanCep}/json/`);
        const data = await response.json();
        if (!data.erro) {
          setChurchData(prev => ({
            ...prev,
            address: `${data.logradouro}, ${data.bairro}`,
            city: data.localidade,
            state: data.uf
          }));
        }
      } catch (error) { console.error("Erro CEP:", error); }
    }
  };

  const handleMemberCepBlur = async (cep: string) => {
    const cleanCep = cep.replace(/\D/g, '');
    if (cleanCep.length === 8) {
      try {
        const response = await fetch(`https://viacep.com.br/ws/${cleanCep}/json/`);
        const data = await response.json();
        if (!data.erro) {
          setEditingMember(prev => prev ? ({
            ...prev,
            address: `${data.logradouro}, ${data.bairro}, ${data.localidade} - ${data.uf}`
          }) : null);
        }
      } catch (error) { console.error("Erro CEP Contato:", error); }
    }
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setChurchData({ ...churchData, logo: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleMemberAvatarUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setEditingMember(prev => prev ? ({ ...prev, avatar: reader.result as string }) : null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleUserAvatarUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setCurrentUser(prev => prev ? ({ ...prev, avatar: reader.result as string }) : null);
      };
      reader.readAsDataURL(file);
    }
  };

  const triggerFileUpload = () => {
    fileInputRef.current?.click();
  };

  const triggerMemberFileUpload = () => {
    memberFileInputRef.current?.click();
  };

  const triggerUserAvatarUpload = () => {
    userAvatarInputRef.current?.click();
  };

  const downloadUserAvatar = () => {
    if (!currentUser?.avatar) return;
    const link = document.createElement('a');
    link.href = currentUser.avatar;
    link.download = `koinonia-perfil-${currentUser.name.toLowerCase().replace(/\s+/g, '-')}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleSaveMember = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingMember?.name) return;

    if (editingMember.id) {
      setMembers(prev => prev.map(m => m.id === editingMember.id ? (editingMember as Member) : m));
    } else {
      const newMember: Member = {
        ...(editingMember as Member),
        id: Math.random().toString(36).substr(2, 9),
        last_activity: new Date(),
        registration_date: new Date(),
        engagement_score: 10,
        church_id: '1',
        channel: editingMember.channel || 'MANUAL',
        responsible_leader_id: editingMember.responsible_leader_id || currentUser?.id
      };
      setMembers(prev => [...prev, newMember]);
    }
    setIsMemberModalOpen(false);
  };

  const handleSaveTeamMember = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingTeamMember?.name) return;
    if (editingTeamMember.id) {
      setTeamMembers(prev => prev.map(u => u.id === editingTeamMember.id ? (editingTeamMember as SystemUser) : u));
    } else {
      const newUser: SystemUser = {
        ...(editingTeamMember as SystemUser),
        id: Math.random().toString(36).substr(2, 9),
        church_id: churchData.name,
        permissions: editingTeamMember.permissions || []
      };
      setTeamMembers(prev => [...prev, newUser]);
    }
    setIsTeamModalOpen(false);
  };

  const handleSaveEvent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEvent.title) return;
    const event: ScheduleEvent = {
      ...newEvent as ScheduleEvent,
      id: Math.random().toString(36).substr(2, 9),
      church_id: '1',
      created_at: new Date()
    };
    setEvents(prev => [...prev, event]);
    setIsEventModalOpen(false);
  };

  const openAddEventModal = (date?: Date, memberId?: string) => {
    setNewEvent({
      title: '',
      type: memberId ? EventType.FOLLOW_UP : EventType.MEETING,
      start_date: date || new Date(),
      end_date: new Date((date || new Date()).getTime() + 3600000),
      member_id: memberId,
      responsible_id: currentUser?.id || ''
    });
    setIsEventModalOpen(true);
  };

  const handleDeleteTeamMember = (id: string) => {
    if (id === currentUser?.id) return alert("Não é possível remover seu próprio usuário.");
    if (confirm("Remover este líder da equipe?")) {
      setTeamMembers(prev => prev.filter(u => u.id !== id));
    }
  };

  const updateCurrentUser = (e: React.FormEvent) => {
    e.preventDefault();
    if (currentUser) {
      localStorage.setItem('koinonia_session', JSON.stringify(currentUser));
      setTeamMembers(prev => prev.map(t => t.id === currentUser.id ? currentUser : t));
      KoinoniaDB.saveTeamMembers(teamMembers.map(t => t.id === currentUser.id ? currentUser : t));
    }

    if (newPassword) {
      alert("Perfil e senha atualizados com sucesso!");
      setNewPassword('');
    } else {
      alert("Perfil atualizado com sucesso!");
    }
    setIsProfileOpen(false);
  };

  const getLeaderName = (id?: string) => {
    if (!id) return 'Não atribuído';
    return teamMembers.find(t => t.id === id)?.name || 'Líder Desconhecido';
  };

  const formatDateForInput = (date: Date | undefined) => {
    if (!date) return '';
    const d = new Date(date);
    d.setMinutes(d.getMinutes() - d.getTimezoneOffset());
    return d.toISOString().slice(0, 16);
  };

  const handleLocationSearch = (query: string) => {
    setNewEvent(prev => ({ ...prev, location: query }));

    if (searchTimeoutRef.current) {
      window.clearTimeout(searchTimeoutRef.current);
    }

    if (query.length > 3) {
      searchTimeoutRef.current = window.setTimeout(async () => {
        setIsSearchingLocation(true);
        try {
          const response = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(query)}&countrycodes=br&limit=5`);
          const data = await response.json();
          setLocationSuggestions(data);
          setShowLocationSuggestions(true);
        } catch (error) {
          console.error("Erro busca Local:", error);
        } finally {
          setIsSearchingLocation(false);
        }
      }, 500);
    } else {
      setShowLocationSuggestions(false);
    }
  };

  const renderMemberListView = () => (
    <div className="overflow-x-auto h-full">
      <table className="w-full text-left border-collapse">
        <thead className="sticky top-0 bg-white shadow-sm z-10">
          <tr className="border-b border-slate-100 text-[10px] font-black text-slate-400 uppercase tracking-widest">
            <th className="px-6 py-4">Nome / Contato</th>
            <th className="px-6 py-4">Estágio</th>
            <th className="px-6 py-4">Engajamento</th>
            <th className="px-6 py-4">Responsável</th>
            <th className="px-6 py-4">Última Ativ.</th>
            <th className="px-6 py-4 text-right">Ações</th>
          </tr>
        </thead>
        <tbody className="divide-y divide-slate-50">
          {members.map(member => (
            <tr key={member.id} className="hover:bg-slate-50/50 transition-colors group">
              <td className="px-6 py-4">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center overflow-hidden border border-slate-200">
                    {member.avatar ? <img src={member.avatar} className="w-full h-full object-cover" alt="Member Avatar" /> : <User className="w-5 h-5 text-slate-400" />}
                  </div>
                  <div>
                    <p className="text-sm font-bold text-slate-800">{member.name}</p>
                    <p className="text-xs text-slate-400 font-medium">{member.email}</p>
                  </div>
                </div>
              </td>
              <td className="px-6 py-4">
                <span className={`px-2 py-0.5 rounded-full text-[10px] font-black uppercase ${STAGES.find(s => s.id === member.stage)?.color}`}>
                  {STAGES.find(s => s.id === member.stage)?.label}
                </span>
              </td>
              <td className="px-6 py-4">
                <div className="flex items-center gap-2">
                  <div className="flex-1 h-1.5 bg-slate-100 rounded-full max-w-[60px] overflow-hidden">
                    <div className="h-full bg-indigo-500 rounded-full" style={{ width: `${member.engagement_score}%` }} />
                  </div>
                  <span className="text-xs font-bold text-slate-600">{member.engagement_score}%</span>
                </div>
              </td>
              <td className="px-6 py-4 text-sm text-slate-500 font-medium">
                {getLeaderName(member.responsible_leader_id)}
              </td>
              <td className="px-6 py-4 text-xs text-slate-400 font-bold">
                {new Date(member.last_activity).toLocaleDateString('pt-BR')}
              </td>
              <td className="px-6 py-4 text-right">
                <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                  <button onClick={() => { setEditingMember(member); setIsMemberModalOpen(true); }} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg"><Edit2 className="w-4 h-4" /></button>
                  <button onClick={() => setMembers(prev => prev.filter(m => m.id !== member.id))} className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg"><Trash2 className="w-4 h-4" /></button>
                </div>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );

  const renderMemberGrid = () => (
    <div className="p-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 overflow-y-auto h-full bg-slate-50/50">
      {members.map(member => (
        <div key={member.id} className="bg-white p-5 rounded-[32px] border border-slate-100 shadow-sm hover:shadow-md transition-all group relative">
          <div className="flex items-start justify-between mb-4">
            <div className="w-14 h-14 rounded-2xl bg-slate-50 border border-slate-100 flex items-center justify-center overflow-hidden">
              {member.avatar ? <img src={member.avatar} className="w-full h-full object-cover" alt="Member Avatar" /> : <User className="w-7 h-7 text-slate-300" />}
            </div>
            <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
              <button onClick={() => { setEditingMember(member); setIsMemberModalOpen(true); }} className="p-1.5 bg-slate-50 text-slate-400 hover:text-indigo-600 rounded-lg"><Edit2 className="w-3.5 h-3.5" /></button>
              <button onClick={() => setMembers(prev => prev.filter(m => m.id !== member.id))} className="p-1.5 bg-slate-50 text-slate-400 hover:text-red-600 rounded-lg"><Trash2 className="w-3.5 h-3.5" /></button>
            </div>
          </div>
          <div className="space-y-1 mb-4">
            <h4 className="font-black text-slate-800 line-clamp-1">{member.name}</h4>
            <p className="text-xs text-slate-400 font-medium line-clamp-1">{member.email}</p>
          </div>
          <div className="flex items-center gap-2 mb-4">
            <span className={`px-2 py-0.5 rounded-lg text-[9px] font-black uppercase ${STAGES.find(s => s.id === member.stage)?.color}`}>
              {STAGES.find(s => s.id === member.stage)?.label}
            </span>
          </div>
          <div className="pt-4 border-t border-slate-50 flex items-center justify-between">
            <div className="flex items-center gap-1.5 text-[10px] text-slate-400 font-bold uppercase">
              <Clock className="w-3 h-3" />
              {new Date(member.last_activity).toLocaleDateString('pt-BR')}
            </div>
            <div className="text-[10px] font-black text-indigo-600 bg-indigo-50 px-2 py-1 rounded-full uppercase">
              Score: {member.engagement_score}%
            </div>
          </div>
        </div>
      ))}
    </div>
  );

  return (
    <div className={`flex h-screen overflow-hidden ${theme === 'dark' ? 'bg-slate-950 text-slate-100' : 'bg-slate-50 text-slate-800'}`}>
      <aside className={`${theme === 'dark' ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'} border-r transition-all duration-300 flex flex-col ${isSidebarOpen ? 'w-64' : 'w-20'}`}>
        <div className="p-6 flex items-center gap-3">
          <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white font-bold text-xl shadow-lg">K</div>
          {isSidebarOpen && <div className="flex flex-col"><span className={`font-bold leading-tight ${theme === 'dark' ? 'text-white' : 'text-slate-800'}`}>Koinonia</span><span className="text-[10px] text-slate-400 uppercase font-bold tracking-tighter">Growth CRM</span></div>}
        </div>
        <nav className="flex-1 mt-6 px-3 space-y-1 overflow-y-auto">
          {navItems.map((item) => (
            <button key={item.id} onClick={() => setActiveTab(item.id as any)} className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl transition-all ${activeTab === item.id ? 'bg-indigo-50 text-indigo-700 font-semibold' : 'text-slate-500 hover:bg-slate-50 hover:text-slate-800'}`}>
              <div className={activeTab === item.id ? 'text-indigo-600' : 'text-slate-400'}>{item.icon}</div>
              {isSidebarOpen && <span>{item.label}</span>}
            </button>
          ))}
        </nav>
        <div className="p-4 mt-auto border-t border-slate-100">
          <button onClick={handleLogout} className="w-full flex items-center gap-3 px-3 py-3 rounded-xl text-slate-500 hover:bg-red-50 hover:text-red-600 transition-all"><LogOut className="w-5 h-5" />{isSidebarOpen && <span>Sair</span>}</button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden">
        <header className={`${theme === 'dark' ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'} h-16 border-b px-6 flex items-center justify-between z-20`}>
          <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 hover:bg-slate-50 rounded-lg text-slate-400">{isSidebarOpen ? <X className="w-5 h-5" /> : <Menu className="w-5 h-5" />}</button>
            <div className="hidden md:flex items-center bg-slate-100 px-3 py-1.5 rounded-xl border border-slate-200">
              <Search className="w-4 h-4 text-slate-400" />
              <input type="text" placeholder="Buscar..." className="bg-transparent border-none focus:ring-0 text-sm w-64 placeholder-slate-400 ml-2 text-slate-800" />
            </div>
          </div>
          <div className="flex items-center gap-4">
            <button className="relative p-2 text-slate-400 hover:bg-slate-50 rounded-lg"><Bell className="w-5 h-5" /><span className="absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full border-2 border-white"></span></button>
            <button onClick={() => setIsProfileOpen(!isProfileOpen)} className="flex items-center gap-3 pl-2 py-1 px-2 rounded-xl hover:bg-slate-50 transition-all">
              <div className="text-right hidden sm:block"><p className={`text-sm font-bold leading-none ${theme === 'dark' ? 'text-white' : 'text-slate-800'}`}>{currentUser?.name}</p><p className="text-[10px] text-slate-400 font-bold uppercase mt-1">{currentUser?.role}</p></div>
              <div className="w-10 h-10 rounded-full bg-blue-50 flex items-center justify-center text-blue-600 border border-blue-100 font-bold text-sm overflow-hidden">
                {currentUser?.avatar ? <img src={currentUser.avatar} className="w-full h-full object-cover" alt="User Profile" /> : currentUser?.name?.[0]}
              </div>
            </button>
            {isProfileOpen && (
              <div className="absolute right-6 top-14 w-72 bg-white rounded-2xl shadow-2xl border border-slate-100 overflow-hidden z-[100] animate-in fade-in slide-in-from-top-2">
                <div className="p-4 border-b border-slate-100 bg-slate-50/50 flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-blue-100 flex items-center justify-center text-blue-700 font-bold overflow-hidden">
                    {currentUser?.avatar ? <img src={currentUser.avatar} className="w-full h-full object-cover" alt="User thumb" /> : currentUser?.name?.[0]}
                  </div>
                  <div className="overflow-hidden">
                    <p className="text-sm font-bold text-slate-800 truncate">{currentUser?.name}</p>
                    <p className="text-xs text-slate-500 truncate">{currentUser?.email}</p>
                  </div>
                </div>
                <div className="p-2">
                  <button onClick={() => {setActiveTab('settings'); setIsProfileOpen(false)}} className="w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-slate-700 hover:bg-slate-50 text-sm">
                    <User className="w-4 h-4 text-slate-400" /> Meu perfil
                  </button>
                </div>
                <div className="p-2 border-t border-slate-100">
                  <button onClick={handleLogout} className="w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-red-600 hover:bg-red-50 text-sm">
                    <LogOut className="w-4 h-4" /> Sair
                  </button>
                </div>
              </div>
            )}
          </div>
        </header>

        <div className="flex-1 overflow-hidden relative">
          {activeTab === 'analytics' && <AnalyticsDashboard members={members} />}
