                   {isSearchingLocation && <Loader2 className="absolute right-3 top-3.5 w-4 h-4 text-indigo-400 animate-spin" />}
                </div>
                {showLocationSuggestions && locationSuggestions.length > 0 && (
                  <div className="absolute z-[120] left-0 right-0 top-full mt-1 bg-white border border-slate-100 shadow-xl rounded-xl overflow-hidden animate-in fade-in slide-in-from-top-1">
