                <div className="grid grid-cols-2 gap-2">
                  {AVAILABLE_PERMISSIONS.map(p => (
                    <label key={p.id} className="flex items-center gap-2 p-2 bg-slate-50 rounded-lg cursor-pointer hover:bg-slate-100 transition-colors">
                      <input 
                        type="checkbox" 
                        checked={editingTeamMember?.permissions?.includes(p.id)} 
                        onChange={e => {
                          const current = editingTeamMember?.permissions || [];
                          const next = e.target.checked ? [...current, p.id] : current.filter(id => id !== p.id);
                          setEditingTeamMember({...editingTeamMember, permissions: next});
                        }} 
                        className="rounded text-indigo-600 focus:ring-indigo-500" 
                      />
                      <span className="text-[10px] font-bold text-slate-600 uppercase">{p.label}</span>
                    </label>
                  ))}
                </div>
              </div>

              <button type="submit" className="w-full py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 active:scale-95 transition-all mt-6">
                Salvar Alterações Equipe
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

