import React from 'react';
import { Member, MemberStage, ScheduleEvent } from '../types';
import { STAGES } from '../constants';
import MemberCard from './MemberCard';
import { Plus, Filter } from 'lucide-react';

interface KanbanBoardProps {
  members: Member[];
  events?: ScheduleEvent[];
  onMoveMember: (id: string, nextStage: MemberStage) => void;
  onAddMember: () => void;
  onMemberClick?: (member: Member) => void;
  onEditEvent?: (event: ScheduleEvent) => void;
}

const KanbanBoard: React.FC<KanbanBoardProps> = ({ members, events = [], onMoveMember, onAddMember, onMemberClick, onEditEvent }) => {
  return (
    <div className="flex flex-col h-full overflow-hidden">
      <div className="flex justify-between items-center p-4 border-b border-slate-200 bg-white">
        <div className="flex items-center gap-4">
          <h2 className="text-xl font-bold text-slate-800">Pipeline de Crescimento</h2>
          <span className="px-2 py-0.5 bg-slate-100 text-slate-600 rounded text-xs font-medium">
            {members.length} Pessoas
          </span>
        </div>
        <div className="flex gap-2">
          <button className="flex items-center gap-2 px-3 py-1.5 bg-white border border-slate-200 rounded-lg text-sm text-slate-600 hover:bg-slate-50">
            <Filter className="w-4 h-4" /> Filtrar
          </button>
          <button 
            onClick={onAddMember}
            className="flex items-center gap-2 px-3 py-1.5 bg-indigo-600 rounded-lg text-sm text-white hover:bg-indigo-700 shadow-sm shadow-indigo-200"
          >
            <Plus className="w-4 h-4" /> Adicionar
          </button>
        </div>
      </div>

      <div className="flex flex-1 overflow-x-auto p-4 gap-4 bg-slate-50 scrollbar-hide">
        {STAGES.map((stage) => {
          const stageMembers = members.filter(m => m.stage === stage.id);

          return (
            <div 
              key={stage.id} 
              className="flex-shrink-0 w-80 flex flex-col h-full"
            >
              <div className={`p-3 rounded-t-xl border-t-4 ${stage.border} bg-white flex justify-between items-center mb-3 shadow-sm`}>
                <div className="flex items-center gap-2">
                  <div className={`p-1.5 rounded-lg ${stage.color}`}>
                    {stage.icon}
                  </div>
                  <h3 className="font-semibold text-slate-700 text-sm uppercase tracking-wider">
                    {stage.label}
                  </h3>
                </div>
                <span className="text-xs text-slate-400 font-bold">
                  {stageMembers.length}
                </span>
              </div>

              <div className="flex-1 overflow-y-auto space-y-3 pr-1 pb-4 scrollbar-thin scrollbar-thumb-slate-200">
                {stageMembers.map(member => (
                  <MemberCard 
                    key={member.id} 
                    member={member} 
                    events={events}
                    onMove={onMoveMember}
                    onClick={onMemberClick}
                    onEditEvent={onEditEvent}
                  />
                ))}

                {stageMembers.length === 0 && (
                  <div className="border-2 border-dashed border-slate-200 rounded-xl p-8 flex flex-col items-center justify-center text-slate-400">
                    <p className="text-xs text-center italic">Nenhum membro neste estágio</p>
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

