  const handleSaveEvent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEvent.title || !newEvent.responsible_id) {
      alert("Título e Responsável são campos obrigatórios.");
      return;
    }

    if (newEvent.id) {
      // Update
      setEvents(prev => prev.map(ev => ev.id === newEvent.id ? (newEvent as ScheduleEvent) : ev));
    } else {
      // Insert
      const event: ScheduleEvent = {
